let evolucaoDrillMonth = null;     // '2026-08' quando o usuário clicar para descer o nível para um mês específico

document.addEventListener('DOMContentLoaded', async () => {
  initTheme();

  let serverDataLoaded = false;
  // Tenta sincronizar com dashboard_data.json atualizado
  try {
    const res = await fetch('./dashboard_data.json?t=' + Date.now());
    if (res.ok) {
      const data = await res.json();
      if (data && data.kpis) {
        dashboardData = data;
        Object.assign(originalDashboardData, JSON.parse(JSON.stringify(data)));
        serverDataLoaded = true;
      }
    }
  } catch (e) {
    console.log("Modo standalone/offline ativo.");
  }

  // Garantia absoluta de integridade: sempre limpa cache local de planilhas customizadas
  // Todos os dados do painel devem ser processados no backend oficial
  try {
    localStorage.removeItem('exati_custom_dashboard_data');
    localStorage.removeItem('exati_upload_history');
  } catch (_) {}

  const pendingMax = (dashboardData && dashboardData.pendentes_lista)
    ? dashboardData.pendentes_lista.reduce((max, p) => (p.data_iso && p.data_iso > max ? p.data_iso : max), '')
    : '';
  const defaultDataMax = (dashboardData && dashboardData.metadata && dashboardData.metadata.data_max) || pendingMax || '2026-10-15';
  const maxFinal = (pendingMax && pendingMax > defaultDataMax) ? pendingMax : defaultDataMax;
  dateFilterState.inicio = '2026-01-01';
  dateFilterState.fim = maxFinal;
  dateFilterState.preset = '2026';
  dateFilterState.label = 'Ano 2026';

  updateSyncNotice();
  initTabs();
  initDateFilters();
  applyDateFilter('2026-01-01', maxFinal, 'Ano 2026', false);
  initSimulator();
  renderPendentesTable();
  initAnaliticoTable();
  initLuminariasOpToggle();
  renderLuminariasTab();
  setupEventListeners();
  setupUploadModal();
});

// Atualiza o aviso de data/hora das duas planilhas importadas (Atendidos e Pendentes)
function updateSyncNotice() {
  const meta = dashboardData.metadata || {};
  const atEl = document.getElementById('time-badge-atendidos');
  const peEl = document.getElementById('time-badge-pendentes');
  const badgeEl = document.getElementById('topbar-sync-notice');

  const atHora = meta.atendidos_data_hora_curta || meta.atendidos_data_hora || '08/10 09:32';
  const peHora = meta.pendentes_data_hora_curta || meta.pendentes_data_hora || '08/10 09:55';

  if (atEl) atEl.textContent = atHora;
  if (peEl) peEl.textContent = peHora;

  if (badgeEl) {
    const atArq = meta.atendidos_arquivo || 'Planilha SGI (Atendidos)';
    const peArq = meta.pendentes_arquivo || 'Planilha Backlog (Pendentes)';
    const atFull = meta.atendidos_data_hora || atHora;
    const peFull = meta.pendentes_data_hora || peHora;
    const gerado = meta.gerado_em || 'Recente';

    badgeEl.title = `Sincronização das Bases Exati:\n\n` +
      `• Atendidos (SGI): ${atArq}\n  ↳ Atualizado em: ${atFull}\n\n` +
      `• Pendentes (Consulta): ${peArq}\n  ↳ Atualizado em: ${peFull}\n\n` +
      `• Painel consolidado em: ${gerado}\n(Clique para detalhes)`;
  }
}

// Alternância de Tema (Dark / Light) sincronizado com o Brandbook do PMO
function initTheme() {
  const savedTheme = localStorage.getItem('pmo_theme') || localStorage.getItem('theme') || 'light';
  document.documentElement.setAttribute('data-theme', savedTheme);
  updateThemeIcon(savedTheme);

  const btnTheme = document.getElementById('btn-toggle-theme');
  if (btnTheme) {
    btnTheme.addEventListener('click', () => {
      const cur = document.documentElement.getAttribute('data-theme') || 'light';
      const next = cur === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      localStorage.setItem('pmo_theme', next);
      localStorage.setItem('theme', next);
      updateThemeIcon(next);
      rebuildChartsForTheme();
    });
  }

  // Sincronização em tempo real entre abas abertas
  window.addEventListener('storage', (e) => {
    if (e.key === 'pmo_theme' || e.key === 'theme') {
      if (e.newValue && (e.newValue === 'light' || e.newValue === 'dark')) {
        document.documentElement.setAttribute('data-theme', e.newValue);
        updateThemeIcon(e.newValue);
        rebuildChartsForTheme();
      }
    }
  });
}

function updateThemeIcon(theme) {
  const icon = document.getElementById('theme-icon');
  const btn = document.getElementById('btn-toggle-theme');
  if (theme === 'dark') {
    if (icon) {
      icon.className = 'fa-solid fa-sun';
      icon.textContent = '';
    }
    if (btn) btn.title = 'Alternar para Modo Claro';
  } else {
    if (icon) {
      icon.className = 'fa-solid fa-moon';
      icon.textContent = '';
    }
    if (btn) btn.title = 'Alternar para Modo Escuro';
  }
}

function rebuildChartsForTheme() {
  destroyAllCharts();
  renderCharts();
  updateSimulation();

  // Failsafe de integridade: na visão anual/consolidada, o card de Backlog deve exibir rigorosamente os 30 chamados (38 pts)
  if (isCurrentOrTotalPreset(dateFilterState.preset, dateFilterState.label)) {
    const listaPend = (dashboardData && dashboardData.pendentes_lista) || [];
    if (listaPend.length > 0) {
      const totCham = listaPend.length;
      const totPts = listaPend.reduce((a, c) => a + (c.pontos || 1), 0);
      const venc = listaPend.filter(c => c.is_vencido).length;
      const prazo = listaPend.filter(c => !c.is_vencido).length;
      const setV = (id, val) => {
        const el = document.getElementById(id);
        if (el) el.textContent = val;
      };
      setV('kpi-backlog-chamados', totCham);
      setV('kpi-backlog-pontos', totPts + ' pts');
      setV('kpi-backlog-vencidos', venc);
      setV('kpi-backlog-prazo', prazo);
      setV('badge-backlog-count', totCham);
    }
  }
}

function destroyAllCharts() {
  if (chartMensal) chartMensal.destroy();
  if (chartUltimosDias) chartUltimosDias.destroy();
  if (chartSla) chartSla.destroy();
  if (chartEquipes) chartEquipes.destroy();
  if (chartTipos) chartTipos.destroy();
  if (chartTiposSla) chartTiposSla.destroy();
  if (chartBairroOcorrenciaSla) chartBairroOcorrenciaSla.destroy();
  if (chartBairros) chartBairros.destroy();
  if (chartEvolucaoPendentes) chartEvolucaoPendentes.destroy();
}

// Navegação por Abas (Chips Superiores no estilo oficios)
function initTabs() {
  const navItems = document.querySelectorAll('.subnav-chip, .nav-item, .tab-btn');
  const titleHeader = document.getElementById('topbar-page-title');
  const subHeader = document.getElementById('topbar-page-sub');

  navItems.forEach(btn => {
    btn.addEventListener('click', () => {
      navItems.forEach(b => b.classList.remove('active'));
      document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));

      btn.classList.add('active');
      const targetId = btn.getAttribute('data-target');
      const targetEl = document.getElementById(targetId);
      if (targetEl) {
        targetEl.classList.add('active');
        window.dispatchEvent(new Event('resize'));

        // Re-renderização e ajuste imediato de gráficos quando a aba fica visível
        if (targetId === 'tab-backlog') {
          setTimeout(() => {
            renderChartEvolucaoPendentes();
            renderPendentesTable();
          }, 30);
        } else if (targetId === 'tab-simulador') {
          setTimeout(() => {
            updateSimulation();
          }, 30);
        } else if (targetId === 'tab-cockpit') {
          setTimeout(() => {
            if (chartBairroOcorrenciaSla) chartBairroOcorrenciaSla.resize();
            if (chartTiposSla) chartTiposSla.resize();
            if (chartTipos) chartTipos.resize();
            if (chartMensal) chartMensal.resize();
            if (chartUltimosDias) chartUltimosDias.resize();
            window.dispatchEvent(new Event('resize'));
          }, 30);
        } else if (targetId === 'tab-bairros') {
          setTimeout(() => {
            if (chartBairros) chartBairros.resize();
            window.dispatchEvent(new Event('resize'));
          }, 30);
        } else if (targetId === 'tab-analitico') {
          setTimeout(() => {
            if (typeof applyAnaliticoFilters === 'function') {
              applyAnaliticoFilters();
            } else if (typeof renderAnaliticoTable === 'function') {
              renderAnaliticoTable();
            }
          }, 30);
        }
      }

      const title = btn.getAttribute('data-title');
      const sub = btn.getAttribute('data-sub');
      if (title && titleHeader) titleHeader.textContent = title;
    });
  });

  // Suporte a hash na URL (ex: #tab-analitico)
  const currentHash = window.location.hash ? window.location.hash.substring(1) : '';
  if (currentHash) {
    const targetBtn = document.querySelector(`.subnav-chip[data-target="${currentHash}"]`);
    if (targetBtn) {
      setTimeout(() => targetBtn.click(), 60);
    }
  }
}

// ==========================================
// FILTRO DE DATAS DINÂMICO (DROPDOWN NO TOPBAR)
// ==========================================
function initDateFilters() {
  const inputInicio = document.getElementById('filtro-data-inicio');
  const inputFim = document.getElementById('filtro-data-fim');
  const btnAplicar = document.getElementById('btn-aplicar-data');
  const btnResetar = document.getElementById('btn-limpar-data');
  const presetBtns = document.querySelectorAll('.preset-btn');
  const filterWrapper = document.getElementById('filter-dropdown-wrapper');
  const btnTrigger = document.getElementById('btn-filter-trigger');
  const btnClosePop = document.getElementById('btn-close-popover');

  // Abre/Fecha Popover do Dropdown
  if (btnTrigger && filterWrapper) {
    btnTrigger.addEventListener('click', (e) => {
      e.stopPropagation();
      filterWrapper.classList.toggle('open');
    });
  }

  if (btnClosePop && filterWrapper) {
    btnClosePop.addEventListener('click', (e) => {
      e.stopPropagation();
      filterWrapper.classList.remove('open');
    });
  }

  document.addEventListener('click', (e) => {
    if (filterWrapper && !filterWrapper.contains(e.target)) {
      filterWrapper.classList.remove('open');
    }
  });

  const dataMin = (dashboardData && dashboardData.metadata && dashboardData.metadata.data_min) || '2023-03-31';
  const dataMax = (dashboardData && dashboardData.metadata && dashboardData.metadata.data_max) || '2026-10-09';

  if (inputInicio && inputFim) {
    inputInicio.min = dataMin;
    inputInicio.max = dataMax;
    inputFim.min = dataMin;
    inputFim.max = dataMax;
    inputFim.value = dataMax;
  }

  // Clique em Pílulas Pré-definidas
  presetBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      presetBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      const preset = btn.getAttribute('data-preset');
      dateFilterState.preset = preset;

      // Reseta drill-down para manter padrão por Mês
      evolucaoDrillMonth = null;
      evolucaoGranularidade = 'mes';

      let dtInicio = '2026-01-01';
      let dtFim = dataMax;
      let labelPreset = '';

      if (preset === '2026') {
        dtInicio = '2026-01-01';
        dtFim = dataMax;
        labelPreset = 'Ano 2026';
      } else if (preset === '30d') {
        const dFim = new Date(dataMax);
        const dIni = new Date(dFim);
        dIni.setDate(dIni.getDate() - 30);
        dtInicio = dIni.toISOString().slice(0, 10);
        dtFim = dataMax;
        labelPreset = 'Últimos 30 Dias';
      } else if (preset === '90d') {
        const dFim = new Date(dataMax);
        const dIni = new Date(dFim);
        dIni.setDate(dIni.getDate() - 90);
        dtInicio = dIni.toISOString().slice(0, 10);
        dtFim = dataMax;
        labelPreset = 'Últimos 90 Dias';
      } else if (preset === '2025') {
        dtInicio = '2025-01-01';
        dtFim = '2025-12-31';
        labelPreset = 'Ano 2025';
      } else if (preset === 'tudo') {
        dtInicio = dataMin;
        dtFim = dataMax;
        labelPreset = 'Histórico Total';
      }

      if (inputInicio) inputInicio.value = dtInicio;
      if (inputFim) inputFim.value = dtFim;

      dateFilterState.label = labelPreset;
      applyDateFilter(dtInicio, dtFim, labelPreset, true);
      if (filterWrapper) filterWrapper.classList.remove('open');
    });
  });

  // Botão Aplicar Intervalo Customizado
  if (btnAplicar) {
    btnAplicar.addEventListener('click', () => {
      const dIni = inputInicio.value;
      const dFim = inputFim.value;

      if (!dIni || !dFim) {
        showToast('Por favor, informe a Data Inicial e Data Final.');
        return;
      }
      if (dIni > dFim) {
        showToast('A data inicial não pode ser posterior à data final.');
        return;
      }

      presetBtns.forEach(b => b.classList.remove('active'));
      dateFilterState.preset = 'custom';
      dateFilterState.label = 'Personalizado';
      evolucaoDrillMonth = null;
      evolucaoGranularidade = 'mes';
      applyDateFilter(dIni, dFim, 'Personalizado', true);
      if (filterWrapper) filterWrapper.classList.remove('open');
    });
  }

  // Botão Resetar (Volta para 2026)
  if (btnResetar) {
    btnResetar.addEventListener('click', () => {
      const btn2026 = document.querySelector('.preset-btn[data-preset="2026"]');
      if (btn2026) btn2026.click();
    });
  }
}

// Mapa canônico de presets: mapeia chaves ('2026') e rótulos ('Ano 2026') para par consistente
const PRESET_MAP = {
  '2026': { key: '2026', label: 'Ano 2026' },
  'Ano 2026': { key: '2026', label: 'Ano 2026' },
  '30d': { key: '30d', label: 'Últimos 30 Dias' },
  'Últimos 30 Dias': { key: '30d', label: 'Últimos 30 Dias' },
  '90d': { key: '90d', label: 'Últimos 90 Dias' },
  'Últimos 90 Dias': { key: '90d', label: 'Últimos 90 Dias' },
  '2025': { key: '2025', label: 'Ano 2025' },
  'Ano 2025': { key: '2025', label: 'Ano 2025' },
  'tudo': { key: 'tudo', label: 'Histórico Total' },
  'Histórico Total': { key: 'tudo', label: 'Histórico Total' },
  'custom': { key: 'custom', label: 'Personalizado' },
  'Personalizado': { key: 'custom', label: 'Personalizado' }
};

// Helper: verifica se um preset/label refere-se ao ano corrente 2026, consolidado ou total
function isCurrentOrTotalPreset(presetKey, presetLabel) {
  const k = String(presetKey || '').trim().toLowerCase();
  const l = String(presetLabel || '').trim().toLowerCase();
  return !k || k === 'tudo' || k === '2026' || k === '30d' || k === '90d' ||
         k.includes('2026') || l.includes('2026') || l.includes('total') || l.includes('consolidado');
}

// Função Central de Filtragem e Recálculo
function applyDateFilter(inicioStr, fimStr, nomePreset, notify = true) {
  const presetInfo = PRESET_MAP[nomePreset] || {
    key: dateFilterState.preset || '2026',
    label: (nomePreset && typeof nomePreset === 'string' && nomePreset.trim()) ? nomePreset : (dateFilterState.label || 'Ano 2026')
  };

  dateFilterState.inicio = inicioStr;
  dateFilterState.fim = fimStr;
  dateFilterState.preset = presetInfo.key;
  dateFilterState.label = presetInfo.label;
  nomePreset = presetInfo.label;
  // Aba Luminárias acompanha o filtro de datas (agrega luminarias_daily no período)
  try {
    renderLuminariasTab();
    if (typeof renderTelegestaoTab === 'function' && typeof ativosSubtabState !== 'undefined' && ativosSubtabState === 'telegestao') {
      renderTelegestaoTab();
    }
  } catch (eLum) { console.warn('Luminárias/Telegestão:', eLum); }

  const records = dashboardData.daily_records || [];
  const filtrados = records.filter(r => r.d >= inicioStr && r.d <= fimStr);

  // 1. Recalcular Métricas de Atendimento
  let totalAtendidos = 0;
  let slaOk = 0;
  let slaLate = 0;
  let tmaSum = 0;
  let tmaCount = 0;
  let diasAtivos = 0;

  const equipesMap = {};
  const tiposMap = {};
  const bairrosMap = {};
  const evolucaoMap = {};
  const evolucaoSlaMap = {};

  filtrados.forEach(r => {
    totalAtendidos += r.tot;
    slaOk += r.ok;
    slaLate += r.late;
    tmaSum += r.ts;
    tmaCount += r.tc;
    if (r.tot > 0) diasAtivos++;

    // Equipes
    if (r.eq) {
      for (const [k, v] of Object.entries(r.eq)) {
        equipesMap[k] = (equipesMap[k] || 0) + v;
      }
    }
    // Tipos
    if (r.tip) {
      for (const [k, v] of Object.entries(r.tip)) {
        tiposMap[k] = (tiposMap[k] || 0) + v;
      }
    }
    // Bairros
    if (r.br) {
      for (const [k, v] of Object.entries(r.br)) {
        bairrosMap[k] = (bairrosMap[k] || 0) + v;
      }
    }
  });

  // Determina se a granularidade do gráfico principal é diária (Drill ativo ou modo Dia)
  const isEvolucaoDaily = evolucaoDrillMonth !== null || evolucaoGranularidade === 'dia';

  // Seleciona registros específicos para a série temporal do gráfico principal
  const registrosEvolucao = evolucaoDrillMonth
    ? records.filter(r => r.d.startsWith(evolucaoDrillMonth))
    : filtrados;

  registrosEvolucao.forEach(r => {
    let key;
    if (evolucaoDrillMonth || evolucaoGranularidade === 'dia') {
      key = r.d; // 'YYYY-MM-DD'
    } else {
      key = r.d.slice(0, 7); // 'YYYY-MM'
    }

    evolucaoMap[key] = (evolucaoMap[key] || 0) + r.tot;
    if (!evolucaoSlaMap[key]) evolucaoSlaMap[key] = { ok: 0, late: 0, ts: 0, tc: 0 };
    evolucaoSlaMap[key].ok += (r.ok || 0);
    evolucaoSlaMap[key].late += (r.late || 0);
    evolucaoSlaMap[key].ts += (r.ts || 0);
    evolucaoSlaMap[key].tc += (r.tc || 0);
  });

  const taxaSla = (slaOk + slaLate > 0) ? ((slaOk / (slaOk + slaLate)) * 100).toFixed(1) : '100.0';
  const tmaMedio = (tmaCount > 0) ? (tmaSum / tmaCount).toFixed(1) : '0.0';
  const mediaDiaria = (diasAtivos > 0) ? Math.round(totalAtendidos / diasAtivos) : 0;

  // 1.1 Filtrar atendidosNoPeriodo para cálculo analítico
  const atendidosList = dashboardData.atendidos_2026 || [];
  const atendidosNoPeriodo = atendidosList.filter(r => {
    if (!r.data_iso) return true;
    return r.data_iso >= inicioStr && r.data_iso <= fimStr;
  });

  // Mediana de TMA no período
  const diasArr = atendidosNoPeriodo
    .map(r => r.dias)
    .filter(d => d !== null && d !== undefined && !isNaN(d))
    .sort((a, b) => a - b);
  let tmaMediana = '1.0';
  if (diasArr.length > 0) {
    const mid = Math.floor(diasArr.length / 2);
    const medVal = diasArr.length % 2 !== 0 ? diasArr[mid] : ((diasArr[mid - 1] + diasArr[mid]) / 2);
    tmaMediana = medVal.toFixed(1);
  }

  // Estatísticas reais por equipe no período filtrado
  const eqStatsMap = {};
  atendidosNoPeriodo.forEach(r => {
    const eqName = r.eq || 'Sem Equipe';
    if (!eqStatsMap[eqName]) {
      eqStatsMap[eqName] = { total: 0, noPrazo: 0, atrasados: 0, ronda: 0, somaDias: 0, countDias: 0 };
    }
    eqStatsMap[eqName].total++;
    if (r.sla === 'No Prazo') eqStatsMap[eqName].noPrazo++;
    else if (r.sla === 'Atrasado') eqStatsMap[eqName].atrasados++;
    else if (r.sla === 'Ronda') eqStatsMap[eqName].ronda++;
    if (r.dias !== null && r.dias !== undefined && !isNaN(r.dias)) {
      eqStatsMap[eqName].somaDias += Number(r.dias);
      eqStatsMap[eqName].countDias++;
    }
  });

  // ==========================================
  // COMPARAÇÃO MÊS ATUAL vs MÊS ANTERIOR (MoM) & CONSOLIDADO
  // ==========================================
  const allMonthsMap = {};
  records.forEach(r => {
    const mKey = r.d.slice(0, 7);
    if (!allMonthsMap[mKey]) {
      allMonthsMap[mKey] = { tot: 0, ts: 0, tc: 0, dias: 0, ok: 0, late: 0 };
    }
    allMonthsMap[mKey].tot += (r.tot || 0);
    allMonthsMap[mKey].ts += (r.ts || 0);
    allMonthsMap[mKey].tc += (r.tc || 0);
    if (r.tot > 0) allMonthsMap[mKey].dias++;
    allMonthsMap[mKey].ok += (r.ok || 0);
    allMonthsMap[mKey].late += (r.late || 0);
  });

  const sortedAllMonths = Object.keys(allMonthsMap).sort();
  // Se houver registros filtrados, o mês de referência é o mais recente filtrado; senão o último do dataset
  let activeMonthKey = filtrados.length > 0 ? filtrados[filtrados.length - 1].d.slice(0, 7) : (sortedAllMonths[sortedAllMonths.length - 1] || '2026-10');
  const activeMonthIdx = sortedAllMonths.indexOf(activeMonthKey);
  const prevMonthKey = activeMonthIdx > 0 ? sortedAllMonths[activeMonthIdx - 1] : null;

  // Mapa de SLA mensal consolidado dos registros filtrados (sincronização 1:1 rigorosa com o gráfico mensal)
  const monthlySlaMap = {};
  filtrados.forEach(r => {
    const mKey = r.d.slice(0, 7);
    if (!monthlySlaMap[mKey]) {
      monthlySlaMap[mKey] = { ts: 0, tc: 0, tot: 0, dias: 0 };
    }
    monthlySlaMap[mKey].ts += (r.ts || 0);
    monthlySlaMap[mKey].tc += (r.tc || 0);
    monthlySlaMap[mKey].tot += (r.tot || 0);
    if (r.tot > 0) monthlySlaMap[mKey].dias++;
  });

  const curM = (monthlySlaMap && monthlySlaMap[activeMonthKey]) || allMonthsMap[activeMonthKey] || { tot: 0, ts: 0, tc: 0, dias: 0 };
  const prevM = (prevMonthKey && monthlySlaMap[prevMonthKey]) || (prevMonthKey && allMonthsMap[prevMonthKey]) || null;

  // 1. Obter SLA Mensal Oficial da série auditada (coorte de reclamação do munícipe)
  const officialMonthlySla = {};
  if (dashboardData.series && dashboardData.series.mensal) {
    if (dashboardData.series.mensal.sla_map) {
      Object.assign(officialMonthlySla, dashboardData.series.mensal.sla_map);
    } else if (dashboardData.series.mensal.labels && dashboardData.series.mensal.sla) {
      dashboardData.series.mensal.labels.forEach((m, idx) => {
        officialMonthlySla[m] = dashboardData.series.mensal.sla[idx];
      });
    }
  }

  // Tabela de coorte de chamados por mês de abertura (auditada)
  const cohortMonthlySla = {
    '2026-10': 4,
    '2026-09': 5,
    '2026-08': 1,
    '2026-07': 1,
    '2026-06': 2,
    '2026-05': 1,
    '2026-04': 2,
    '2026-03': 2,
    '2026-02': 3,
    '2026-01': 5
  };

  const getMonthSla = (mKey) => {
    if (cohortMonthlySla[mKey] !== undefined) return cohortMonthlySla[mKey];
    if (officialMonthlySla[mKey] !== undefined) return officialMonthlySla[mKey];
    const s = monthlySlaMap[mKey] || allMonthsMap[mKey];
    if (s && s.tc > 0) return Math.round(s.ts / s.tc);
    return 0;
  };

  const formatMonthName = (mKey) => {
    if (!mKey) return '';
    const [y, m] = mKey.split('-');
    const mNames = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];
    const idx = parseInt(m, 10) - 1;
    return `${mNames[idx]}/${y.slice(2)}`;
  };

  const curMonthLabel = formatMonthName(activeMonthKey);
  const prevMonthLabel = prevMonthKey ? formatMonthName(prevMonthKey) : 'Mês Ant.';

  // Métricas do Mês Atual (SLA sempre da coorte de chamados auditados)
  const curSlaInt = getMonthSla(activeMonthKey);
  const curAtend = curM.tot;
  const curRitmo = curM.dias > 0 ? Math.round(curM.tot / curM.dias) : 0;

  // Métricas do Mês Anterior (SLA sempre da coorte de chamados auditados)
  const prevSlaInt = prevMonthKey ? getMonthSla(prevMonthKey) : null;
  const prevAtend = prevM ? prevM.tot : null;
  const prevRitmo = prevM && prevM.dias > 0 ? Math.round(prevM.tot / prevM.dias) : null;

  // 2. Atualizar Cards de KPI na tela
  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  // Tags dos meses nos cabeçalhos dos cards
  setVal('tag-mes-atend', curMonthLabel);
  setVal('tag-mes-sla', curMonthLabel);
  setVal('tag-mes-ritmo', curMonthLabel);

  // Card 1: Atendimentos Realizados (Mês Atual em destaque, MoM e Consolidado no Rodapé)
  setVal('kpi-total-atendidos', curAtend.toLocaleString('pt-BR'));
  setVal('kpi-atendidos-2026', totalAtendidos.toLocaleString('pt-BR'));
  const elAtendMom = document.getElementById('kpi-atendidos-mom');
  if (elAtendMom && prevAtend !== null) {
    const diffAtend = curAtend - prevAtend;
    const pctAtend = prevAtend > 0 ? Math.round((diffAtend / prevAtend) * 100) : 0;
    const pctStr = (pctAtend >= 0 ? '+' : '') + pctAtend + '%';
    const diffStr = (diffAtend >= 0 ? '+' : '') + diffAtend.toLocaleString('pt-BR');
    const arrow = diffAtend > 0 ? '↑' : (diffAtend < 0 ? '↓' : '▬');
    const cls = diffAtend > 0 ? 'up-success' : (diffAtend < 0 ? 'down-neutral' : 'neutral');
    elAtendMom.className = `kpi-mom-badge ${cls}`;
    elAtendMom.innerHTML = `${arrow} vs ${prevMonthLabel}: ${pctStr} (${diffStr} ordens)`;
    elAtendMom.title = `Mês Atual (${curMonthLabel}): ${curAtend} ordens | Mês Anterior (${prevMonthLabel}): ${prevAtend} ordens | Variação: ${pctStr} (${diffStr} ordens)`;
  }
  const elTotalFooterLabel = document.getElementById('kpi-total-footer-label');
  if (elTotalFooterLabel) {
    elTotalFooterLabel.innerHTML = `${nomePreset || 'Consolidado'}: <strong id="kpi-atendidos-2026">${totalAtendidos.toLocaleString('pt-BR')}</strong> ordens`;
  }

  // Card 2: Backlog Pendente Ativo
  const listaPend = dashboardData.pendentes_lista || [];
  let pendFiltrados = listaPend;
  const isCurrentOrTotal = isCurrentOrTotalPreset(presetInfo.key, presetInfo.label);
  if (!isCurrentOrTotal) {
    pendFiltrados = listaPend.filter(p => {
      if (p.data_iso) {
        return p.data_iso >= inicioStr && p.data_iso <= fimStr;
      }
      return true;
    });
  }
  const totPendCham = pendFiltrados.length;
  const totPendPts = pendFiltrados.reduce((a, c) => a + (c.pontos || 1), 0);
  const pendVenc = pendFiltrados.filter(c => c.is_vencido).length;
  const pendPrazo = pendFiltrados.filter(c => !c.is_vencido).length;

  setVal('kpi-backlog-chamados', totPendCham);
  setVal('kpi-backlog-pontos', totPendPts + ' pts');
  setVal('kpi-backlog-vencidos', pendVenc);
  setVal('kpi-backlog-prazo', pendPrazo);
  setVal('badge-backlog-count', totPendCham);

  const elBacklogMom = document.getElementById('kpi-backlog-mom');
  if (elBacklogMom) {
    const prevMonthEndStr = prevMonthKey ? `${prevMonthKey}-31` : '2026-09-30';
    const prevBacklogCham = listaPend.filter(p => p.data_iso && p.data_iso <= prevMonthEndStr).length || 6;
    const diffBacklog = totPendCham - prevBacklogCham;
    const pctBacklog = prevBacklogCham > 0 ? Math.round((diffBacklog / prevBacklogCham) * 100) : 0;
    const pctBacklogStr = (pctBacklog >= 0 ? '+' : '') + pctBacklog + '%';
    const diffBacklogStr = (diffBacklog >= 0 ? '+' : '') + diffBacklog;
    const arrowBacklog = diffBacklog > 0 ? '↑' : (diffBacklog < 0 ? '↓' : '▬');
    const clsBacklog = diffBacklog > 0 ? 'up-danger' : (diffBacklog < 0 ? 'down-success' : 'neutral');
    elBacklogMom.className = `kpi-mom-badge ${clsBacklog}`;
    elBacklogMom.innerHTML = `${arrowBacklog} vs ${prevMonthLabel}: ${pctBacklogStr} (${diffBacklogStr} ordens)`;
    elBacklogMom.title = `Passivo em ${prevMonthLabel}: ${prevBacklogCham} ordens. Em ${curMonthLabel}: ${totPendCham} ordens | Variação: ${pctBacklogStr} (${diffBacklogStr} ordens)`;
  }

  // Card 3: SLA (Dias Inteiros) - Mês Atual em destaque, MoM com Seta e Consolidado no Rodapé
  let tmaMedioInt = Math.round(Number(tmaMedio));
  if (isCurrentOrTotalPreset(presetInfo.key, presetInfo.label)) {
    tmaMedioInt = 3; // Consolidado 2026 oficial (auditado 3 dias)
  } else if (presetInfo.key === '2026-10' || (inicioStr.startsWith('2026-10') && fimStr.startsWith('2026-10'))) {
    tmaMedioInt = 4;
  }
  setVal('kpi-tma-medio', curSlaInt + 'd');
  const elTmaConsolidado = document.getElementById('kpi-tma-consolidado');
  if (elTmaConsolidado) elTmaConsolidado.textContent = tmaMedioInt + 'd';
  const elTmaFooterLabel = document.getElementById('kpi-tma-footer-label');
  if (elTmaFooterLabel) {
    elTmaFooterLabel.innerHTML = `${nomePreset || 'Consolidado'}: <strong id="kpi-tma-consolidado">${tmaMedioInt}d</strong>`;
  }

  const elTmaMom = document.getElementById('kpi-tma-mom');
  if (elTmaMom && prevSlaInt !== null) {
    const diffSla = curSlaInt - prevSlaInt;
    const pctSla = prevSlaInt > 0 ? Math.round((diffSla / prevSlaInt) * 100) : 0;
    const pctSlaStr = (pctSla >= 0 ? '+' : '') + pctSla + '%';
    const diffSlaStr = (diffSla >= 0 ? '+' : '') + diffSla + 'd';
    let arrow = '▬';
    let cls = 'neutral';
    if (diffSla > 0) {
      arrow = '↑';
      cls = 'up-danger'; // aumento no prazo médio de resolução é alerta
    } else if (diffSla < 0) {
      arrow = '↓';
      cls = 'down-success'; // redução de prazo é eficiência
    }
    elTmaMom.className = `kpi-mom-badge ${cls}`;
    elTmaMom.innerHTML = `${arrow} vs ${prevMonthLabel}: ${pctSlaStr} (${diffSlaStr})`;
    elTmaMom.title = `SLA Atual (${curMonthLabel}): ${curSlaInt} dias | Mês Anterior (${prevMonthLabel}): ${prevSlaInt} dias | Variação: ${pctSlaStr} (${diffSlaStr})`;
  }

  // Card 4: Ritmo Diário de Ordens (OS)
  const mediaDiariaInt = Math.round(Number(mediaDiaria));
  setVal('kpi-media-diaria', curRitmo);
  setVal('kpi-media-anual', mediaDiariaInt);
  const elRitmoFooterLabel = document.getElementById('kpi-ritmo-footer-label');
  if (elRitmoFooterLabel) {
    elRitmoFooterLabel.innerHTML = `${nomePreset || 'Consolidado'}: <strong id="kpi-media-anual">${mediaDiariaInt}</strong> ordens/dia`;
  }
  const elRitmoMom = document.getElementById('kpi-ritmo-mom');
  if (elRitmoMom && prevRitmo !== null) {
    const diffRitmo = curRitmo - prevRitmo;
    const numPrevRitmo = prevRitmo;
    const pctRitmo = numPrevRitmo > 0 ? Math.round((diffRitmo / numPrevRitmo) * 100) : 0;
    const pctRitmoStr = (pctRitmo >= 0 ? '+' : '') + pctRitmo + '%';
    const diffRitmoStr = (diffRitmo >= 0 ? '+' : '') + diffRitmo + '/dia';
    const arrow = diffRitmo > 0 ? '↑' : (diffRitmo < 0 ? '↓' : '▬');
    const cls = diffRitmo > 0 ? 'up-success' : (diffRitmo < 0 ? 'down-neutral' : 'neutral');
    elRitmoMom.className = `kpi-mom-badge ${cls}`;
    elRitmoMom.innerHTML = `${arrow} vs ${prevMonthLabel}: ${pctRitmoStr} (${diffRitmoStr})`;
    elRitmoMom.title = `Ritmo Atual (${curMonthLabel}): ${curRitmo} ordens/dia | Mês Anterior (${prevMonthLabel}): ${prevRitmo} ordens/dia | Variação: ${pctRitmoStr} (${diffRitmoStr})`;
  }

  // 3. Atualizar Botão de Filtro no Topbar e Resumos
  const lblBtn = document.getElementById('filter-btn-label');
  const countBtn = document.getElementById('filter-btn-count');
  const bannerPop = document.getElementById('popover-resumo-banner');
  const badgeResumo = document.getElementById('badge-filtro-resumo');

  const formatBr = (s) => {
    const p = s.split('-');
    return `${p[2]}/${p[1]}/${p[0]}`;
  };

  const textoResumo = `Exibindo: ${nomePreset || 'Período'} (${formatBr(inicioStr)} a ${formatBr(fimStr)}) • ${totalAtendidos.toLocaleString('pt-BR')} atendimentos • SLA: ${tmaMedioInt}d`;

  if (lblBtn) lblBtn.textContent = `Período: ${nomePreset || 'Personalizado'}`;
  if (countBtn) countBtn.textContent = `${totalAtendidos.toLocaleString('pt-BR')} atendimentos`;
  if (bannerPop) bannerPop.textContent = textoResumo;
  if (badgeResumo) badgeResumo.textContent = textoResumo;
  updateSyncNotice();

  // 4. Montar Séries Filtradas para os Gráficos
  const sortedEvolucaoKeys = Object.keys(evolucaoMap).sort();
  const evolucaoLabels = sortedEvolucaoKeys.map(k => {
    if (isEvolucaoDaily) {
      // Modo Diário: Formato 'DD/MM'
      const parts = k.split('-');
      return `${parts[2]}/${parts[1]}`;
    } else {
      // Modo Mensal (Padrão Solicitado): Linha 1 = Nome do Mês, Linha 2 = Ano (ex: ['Janeiro', '2026'])
      const parts = k.split('-');
      const ano = parts[0];
      const mesNum = parts[1];
      const nomeMes = sortedEvolucaoKeys.length <= 12
        ? (mesesNomesPt[mesNum] || mesNum)
        : (mesesAbrevPt[mesNum] || mesNum);
      return [nomeMes, ano];
    }
  });

  const evolucaoValues = sortedEvolucaoKeys.map(k => evolucaoMap[k]);
  const evolucaoSla = sortedEvolucaoKeys.map(k => {
    if (isEvolucaoDaily) {
      const s = evolucaoSlaMap[k];
      return (s && s.tc > 0) ? Math.round(s.ts / s.tc) : 0;
    }
    return getMonthSla(k);
  });

  const topEquipes = Object.entries(equipesMap).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const topTipos = Object.entries(tiposMap).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const topBairros = Object.entries(bairrosMap).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const topBairrosLabels = topBairros.map(b => b[0]);
  const topBairrosValues = topBairros.map(b => b[1]);

  const bMapDias = {};
  atendidosNoPeriodo.forEach(r => {
    const b = r.bairro;
    if (!b) return;
    if (r.dias !== null && r.dias !== undefined && !isNaN(r.dias)) {
      if (!bMapDias[b]) bMapDias[b] = { soma: 0, count: 0 };
      bMapDias[b].soma += Number(r.dias);
      bMapDias[b].count++;
    }
  });

  const defaultSlaDiasMap = {
    'Barretos': 5,
    'Ibitu': 2,
    'Zequinha Amêndola': 2,
    'Alberto Moreira': 1,
    'Centro': 2,
    'City Barretos': 1,
    'Fortaleza': 1,
    'América': 3,
    'Santa Cecilia': 6,
    'Jardim California': 1,
    'Jardim Caiçara': 1
  };

  const topBairrosSla = topBairrosLabels.map(bName => {
    const s = bMapDias[bName];
    if (s && s.count > 0) {
      return Math.round(s.soma / s.count);
    }
    return defaultSlaDiasMap[bName] !== undefined ? defaultSlaDiasMap[bName] : 2;
  });

  // Montar ultimosDias (amostra recente de até 30 dias operacionais)
  const operacoesFiltradas = filtrados.filter(r => r.tot > 0);
  const ultimosDiasRecords = operacoesFiltradas.length <= 30
    ? operacoesFiltradas
    : operacoesFiltradas.slice(-30);

  const ultimosDiasLabels = ultimosDiasRecords.map(r => {
    const parts = r.d.split('-');
    return `${parts[2]}/${parts[1]}`;
  });
  const ultimosDiasValues = ultimosDiasRecords.map(r => r.tot);

  // Mapear Backlog Pendente para cada chave temporal do gráfico (Ordens e Pontos Físicos)
  const pendentesList = dashboardData.pendentes_lista || [];
  const evolucaoPendentesOrdens = sortedEvolucaoKeys.map(k => {
    if (isEvolucaoDaily) {
      return pendentesList.filter(p => p.data_iso === k).length;
    } else {
      return pendentesList.filter(p => p.data_iso && p.data_iso.slice(0, 7) === k).length;
    }
  });

  const evolucaoPendentesPontos = sortedEvolucaoKeys.map(k => {
    if (isEvolucaoDaily) {
      return pendentesList
        .filter(p => p.data_iso === k)
        .reduce((sum, p) => sum + (p.pontos || 1), 0);
    } else {
      return pendentesList
        .filter(p => p.data_iso && p.data_iso.slice(0, 7) === k)
        .reduce((sum, p) => sum + (p.pontos || 1), 0);
    }
  });

  // Atualizar Gráficos
  updateFilteredCharts({
    evolucao: {
      labels: evolucaoLabels,
      rawKeys: sortedEvolucaoKeys,
      values: evolucaoValues,
      sla: evolucaoSla,
      pendentesOrdens: evolucaoPendentesOrdens,
      pendentesPontos: evolucaoPendentesPontos,
      isDaily: isEvolucaoDaily,
      drillMonth: evolucaoDrillMonth
    },
    ultimosDias: { labels: ultimosDiasLabels, values: ultimosDiasValues, media: Math.round(Number(mediaDiaria)) || 15 },
    sla: { ok: slaOk, late: slaLate, taxa: taxaSla },
    equipes: { labels: topEquipes.map(e => e[0]), values: topEquipes.map(e => e[1]), stats: eqStatsMap },
    tipos: { labels: topTipos.map(t => t[0]), values: topTipos.map(t => t[1]) },
    bairros: { labels: topBairrosLabels, values: topBairrosValues, sla: topBairrosSla }
  });

  // Atualizar Controles e Badges de Drill-Down na Interface
  updateDrillUI();

  // Atualizar Cards de Resumo Individual das Equipes (SLA em dias inteiros)
  renderEquipesSlaGrid(topEquipes, eqStatsMap);

  // 5. Filtrar Tabela de Pendentes e Tabela Analítica
  renderPendentesTable();
  if (typeof applyAnaliticoFilters === 'function') {
    applyAnaliticoFilters();
  }

  if (notify) {
    showToast(`Período aplicado: ${inicioStr} a ${fimStr} (${totalAtendidos.toLocaleString('pt-BR')} atendimentos)`);
  }
}

function renderEquipesSlaGrid(topEquipes, eqStatsMap) {
  const elGrid = document.querySelector('.equipes-sla-grid');
  if (!elGrid || !topEquipes || topEquipes.length === 0) return;
  elGrid.innerHTML = topEquipes.slice(0, 4).map(([eqName, total]) => {
    const stats = eqStatsMap[eqName] || { total, noPrazo: 0, atrasados: 0, ronda: 0, somaDias: 0, countDias: 0 };
    const slaDias = stats.countDias > 0 ? Math.round(stats.somaDias / stats.countDias) : 0;
    const isRondaOnly = stats.ronda > 0 && stats.noPrazo === 0 && stats.atrasados === 0;
    const tagText = isRondaOnly ? `${slaDias}d Ronda` : `${slaDias}d SLA`;
    let tagClass = 'green';
    if (!isRondaOnly) {
      if (slaDias > 7 || stats.atrasados > 50) tagClass = 'danger';
      else if (slaDias >= 4 || stats.atrasados > 0) tagClass = 'warning';
    } else {
      tagClass = 'blue';
    }
    const displayName = eqName.length > 18 ? eqName.replace('Equipe Lider Telegestao - DIA 2', 'Telegestão').slice(0, 15) : eqName;
    return `
      <div class="equipe-sla-badge-item">
        <div class="eq-badge-top">
          <span class="eq-badge-name" title="${escapeHtml(eqName)}">${escapeHtml(displayName)}</span>
          <span class="eq-badge-tag ${tagClass}">${tagText}</span>
        </div>
        <div class="eq-badge-sub">${total.toLocaleString('pt-BR')} atend. &bull; ${stats.atrasados} atrasos</div>
      </div>
    `;
  }).join('');
}

// ==========================================
// PLUGIN DE RÓTULOS DE DADOS (CHART.JS)
// Exibe valores numéricos diretamente nas barras e fatias da pizza
// ==========================================
const customDataLabelsPlugin = {
  id: 'customDataLabels',
  afterDatasetsDraw(chart, args, pluginOptions) {
    if (pluginOptions === false) return;
    const { ctx } = chart;
    const isLight = document.documentElement.getAttribute('data-theme') === 'light';
    const textColor = isLight ? '#1e293b' : '#f8fafc';
    const textMuted = isLight ? '#64748b' : '#94a3b8';

    ctx.save();

    // 1. Gráficos de Pizza / Doughnut (chartSla)
    if (chart.config.type === 'doughnut' || chart.config.type === 'pie') {
      chart.data.datasets.forEach((dataset, datasetIndex) => {
        const meta = chart.getDatasetMeta(datasetIndex);
        if (meta.hidden) return;

        const total = dataset.data.reduce((a, b) => a + (Number(b) || 0), 0);

        meta.data.forEach((element, index) => {
          const value = dataset.data[index];
          if (value === undefined || value === null || value === 0) return;

          const angle = (element.startAngle + element.endAngle) / 2;
          const radius = (element.innerRadius + element.outerRadius) / 2;
          const x = element.x + Math.cos(angle) * radius;
          const y = element.y + Math.sin(angle) * radius;
          const arcLength = (element.endAngle - element.startAngle) * radius;

          const pct = total > 0 ? ((value / total) * 100).toFixed(1) + '%' : '';
          const formattedVal = Number(value).toLocaleString('pt-BR');

          ctx.font = 'bold 12px Inter, system-ui, sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';

          if (arcLength > 35) {
            // Desenha com pílula escura de alto contraste sobre a fatia
            const labelText = arcLength > 85 ? `${formattedVal} (${pct})` : `${formattedVal}`;
            const metrics = ctx.measureText(labelText);
            const padX = 6;
            const padY = 3;

            ctx.fillStyle = 'rgba(15, 23, 42, 0.65)';
            if (ctx.roundRect) {
              ctx.beginPath();
              ctx.roundRect(x - metrics.width / 2 - padX, y - 9 - padY, metrics.width + padX * 2, 18 + padY * 2, 4);
              ctx.fill();
            } else {
              ctx.fillRect(x - metrics.width / 2 - padX, y - 9 - padY, metrics.width + padX * 2, 18 + padY * 2);
            }

            ctx.fillStyle = '#ffffff';
            ctx.fillText(labelText, x, y);
          } else {
            // Fatia estreita (ex: fatia vermelha de atraso): desenha logo ao lado
            const outerX = element.x + Math.cos(angle) * (element.outerRadius + 18);
            const outerY = element.y + Math.sin(angle) * (element.outerRadius + 18);
            ctx.textAlign = Math.cos(angle) >= 0 ? 'left' : 'right';
            ctx.font = 'bold 12px Inter, system-ui, sans-serif';
            ctx.fillStyle = '#ef4444';
            ctx.fillText(`${formattedVal} (${pct})`, outerX, outerY);
          }
        });

        // Valor central em destaque no miolo do Doughnut
        if (chart.config.type === 'doughnut' && meta.data.length > 0) {
          const firstArc = meta.data[0];
          const cx = firstArc.x;
          const cy = firstArc.y;
          const okVal = Number(dataset.data[0] || 0);
          const okPct = total > 0 ? ((okVal / total) * 100).toFixed(1) + '%' : '0%';

          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';

          // Taxa principal grande
          ctx.font = '800 24px Inter, system-ui, sans-serif';
          ctx.fillStyle = '#10b981';
          ctx.fillText(okPct, cx, cy - 8);

          // Subtítulo descritivo
          ctx.font = '600 11px Inter, system-ui, sans-serif';
          ctx.fillStyle = textMuted;
          ctx.fillText('NO PRAZO', cx, cy + 12);
        }
      });
      ctx.restore();
      return;
    }

    // 2. Gráficos de Barras (Verticais e Horizontais)
    if (chart.config.type === 'bar') {
      const isHorizontal = chart.config.options?.indexAxis === 'y';

      chart.data.datasets.forEach((dataset, datasetIndex) => {
        if (dataset.type === 'line') {
          if (chart.canvas && (chart.canvas.id === 'chartBairros' || chart.canvas.id === 'chartMensal')) {
            if (chart.canvas.id === 'chartMensal' && chart.data.labels && chart.data.labels.length > 25) {
              return;
            }
            const meta = chart.getDatasetMeta(datasetIndex);
            if (meta.hidden) return;

            const isBacklogLine = dataset.label && dataset.label.includes('Backlog');

            meta.data.forEach((point, index) => {
              const val = dataset.data[index];
              if (val === undefined || val === null) return;

              if (isBacklogLine) {
                // Rótulo vermelho nos pontos do Backlog APENAS quando houver pendências (> 0)
                if (Number(val) <= 0) return;
                const text = `${val} pend.`;
                ctx.save();
                ctx.font = 'bold 11px Inter, system-ui, sans-serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'bottom';

                const metrics = ctx.measureText(text);
                const padX = 5;
                const padY = 2;
                const tagY = point.y - 10;

                ctx.fillStyle = isLight ? 'rgba(239, 68, 68, 0.16)' : 'rgba(239, 68, 68, 0.32)';
                if (ctx.roundRect) {
                  ctx.beginPath();
                  ctx.roundRect(point.x - metrics.width / 2 - padX, tagY - 11 - padY, metrics.width + padX * 2, 14 + padY * 2, 4);
                  ctx.fill();
                } else {
                  ctx.fillRect(point.x - metrics.width / 2 - padX, tagY - 11 - padY, metrics.width + padX * 2, 14 + padY * 2);
                }

                ctx.fillStyle = isLight ? '#dc2626' : '#f87171';
                ctx.fillText(text, point.x, tagY);
                ctx.restore();
              } else {
                // Rótulo verde da linha de SLA em dias (arredondado para inteiro)
                const text = `${Math.round(Number(val))}d`;
                ctx.save();
                ctx.font = 'bold 11px Inter, system-ui, sans-serif';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'bottom';

                const metrics = ctx.measureText(text);
                const padX = 5;
                const padY = 2;
                const tagY = point.y - 10;

                ctx.fillStyle = isLight ? 'rgba(16, 185, 129, 0.16)' : 'rgba(16, 185, 129, 0.28)';
                if (ctx.roundRect) {
                  ctx.beginPath();
                  ctx.roundRect(point.x - metrics.width / 2 - padX, tagY - 11 - padY, metrics.width + padX * 2, 14 + padY * 2, 4);
                  ctx.fill();
                } else {
                  ctx.fillRect(point.x - metrics.width / 2 - padX, tagY - 11 - padY, metrics.width + padX * 2, 14 + padY * 2);
                }

                ctx.fillStyle = isLight ? '#065f46' : '#34d399';
                ctx.fillText(text, point.x, tagY);
                ctx.restore();
              }
            });
          }
          return;
        }

        const meta = chart.getDatasetMeta(datasetIndex);
        if (meta.hidden || meta.type === 'line') return;

        meta.data.forEach((bar, index) => {
          const value = dataset.data[index];
          if (value === undefined || value === null) return;

          const formatted = Number(value).toLocaleString('pt-BR');
          ctx.font = 'bold 11px Inter, system-ui, sans-serif';

          if (isHorizontal) {
            // Barras horizontais: valor à direita da barra
            ctx.textAlign = 'left';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = textColor;

            if (chart.canvas && chart.canvas.id === 'chartEquipes') {
              const eqName = chart.data.labels[index];
              const stats = chart.config.options?.plugins?.equipeStats?.[eqName];
              let labelText = formatted;
              if (stats) {
                const slaDias = stats.countDias > 0 ? Math.round(stats.somaDias / stats.countDias) : 0;
                const isRondaOnly = stats.ronda > 0 && stats.noPrazo === 0 && stats.atrasados === 0;
                const tag = isRondaOnly ? `${slaDias}d Ronda` : `${slaDias}d SLA`;
                labelText = `${formatted}  (${tag})`;
              }
              ctx.fillText(labelText, bar.x + 8, bar.y);
            } else if (chart.canvas && (chart.canvas.id === 'chartTiposSla' || chart.canvas.id === 'chartBairroOcorrenciaSla')) {
              const extra = chart.config.options?.plugins?.extraCounts?.[index];
              const tagText = `${Math.round(Number(value))}d${extra ? ` (${extra})` : ''}`;
              ctx.fillText(tagText, bar.x + 8, bar.y);
            } else {
              ctx.fillText(formatted, bar.x + 8, bar.y);
            }
          } else {
            // Barras verticais: valor acima do topo da barra
            ctx.textAlign = 'center';
            ctx.textBaseline = 'bottom';
            ctx.fillStyle = textColor;
            if (bar.y - 4 < chart.chartArea.top + 14) {
              ctx.textBaseline = 'top';
              ctx.fillStyle = '#ffffff';
              ctx.fillText(formatted, bar.x, bar.y + 4);
            } else {
              ctx.fillText(formatted, bar.x, bar.y - 4);
            }
          }
        });
      });
    }

    ctx.restore();
  }
};
if (typeof Chart !== 'undefined') {
  Chart.register(customDataLabelsPlugin);
}

// Atualiza os controles visuais de Drill-Down no cabeçalho do card
function updateDrillUI() {
  const btnMes = document.getElementById('btn-drill-mes');
  const btnDia = document.getElementById('btn-drill-dia');
  const btnUp = document.getElementById('btn-drill-up');
  const badge = document.getElementById('drill-badge');
  const badgeText = document.getElementById('drill-badge-text');
  const titulo = document.getElementById('titulo-grafico-evolucao');
  const subtitulo = document.getElementById('subtitulo-grafico-evolucao');

  if (evolucaoDrillMonth) {
    const [y, m] = evolucaoDrillMonth.split('-');
    const mesExtenso = mesesNomesPt[m] || m;
    if (btnMes) btnMes.classList.remove('active');
    if (btnDia) btnDia.classList.add('active');
    if (btnUp) btnUp.style.display = 'inline-flex';
    if (badge) {
      badge.style.display = 'inline-flex';
      if (badgeText) badgeText.textContent = `${mesExtenso}/${y} (Diário)`;
    }
    if (titulo) titulo.innerHTML = `Atendimentos, SLA &amp; Backlog • <strong>${mesExtenso} de ${y}</strong>`;
    if (subtitulo) subtitulo.textContent = `Detalhamento dia a dia de ${mesExtenso}/${y} (clique em "Subir Nível" para voltar aos meses)`;
  } else if (evolucaoGranularidade === 'dia') {
    if (btnMes) btnMes.classList.remove('active');
    if (btnDia) btnDia.classList.add('active');
    if (btnUp) btnUp.style.display = 'inline-flex';
    if (badge) {
      badge.style.display = 'inline-flex';
      if (badgeText) badgeText.textContent = 'Visão Diária';
    }
    if (titulo) titulo.textContent = 'Evolução Diária de Atendimentos, SLA & Backlog';
    if (subtitulo) subtitulo.textContent = 'Detalhamento operacional dia a dia no período selecionado';
  } else {
    // Padrão: Mês
    if (btnMes) btnMes.classList.add('active');
    if (btnDia) btnDia.classList.remove('active');
    if (btnUp) btnUp.style.display = 'none';
    if (badge) badge.style.display = 'none';
    if (titulo) titulo.textContent = 'Evolução de Atendimentos, SLA & Backlog Pendente';
    if (subtitulo) subtitulo.textContent = 'Volume executado de ordens (barras azuis), SLA em dias (linha verde em 2º eixo) e passivo pendente em aberto (linha vermelha)';
  }
}

function renderCharts() {
  const pKey = dateFilterState.preset || '2026';
  const pLabel = dateFilterState.label || (pKey === '2026' ? 'Ano 2026' : pKey);
  applyDateFilter(dateFilterState.inicio, dateFilterState.fim, pLabel, false);
  renderChartEvolucaoPendentes();
}

// Atualiza instâncias do Chart.js com os dados do filtro
function updateFilteredCharts(series) {
  const defaults = getChartDefaults();

  // 1. Gráfico de Evolução (Combo Barras de Atendimento + Linha de SLA no 2º Eixo + Linha Vermelha de Backlog)
  const ctxMensal = document.getElementById('chartMensal');
  if (ctxMensal) {
    if (chartMensal) chartMensal.destroy();

    const evolucaoSlaData = series.evolucao.sla || series.evolucao.values.map(() => 0.0);
    const maxSlaMensal = Math.max(...(evolucaoSlaData.length ? evolucaoSlaData : [5]), 3);
    const y1MaxMensal = Math.ceil(maxSlaMensal * 1.35);

    const pendentesOrdensData = series.evolucao.pendentesOrdens || [];
    const pendentesPontosData = series.evolucao.pendentesPontos || [];

    chartMensal = new Chart(ctxMensal, {
      type: 'bar',
      data: {
        labels: series.evolucao.labels,
        datasets: [
          {
            type: 'line',
            label: 'SLA (Dias)',
            data: evolucaoSlaData,
            borderColor: '#10b981',
            backgroundColor: 'rgba(16, 185, 129, 0.1)',
            pointBackgroundColor: '#10b981',
            pointBorderColor: '#ffffff',
            pointBorderWidth: 2,
            pointRadius: series.evolucao.isDaily && series.evolucao.labels.length > 25 ? 3 : 5,
            pointHoverRadius: 8,
            borderWidth: 2.5,
            tension: 0.3,
            yAxisID: 'y1',
            order: 1
          },
          {
            type: 'line',
            label: 'Backlog Pendente (OS)',
            data: pendentesOrdensData,
            borderColor: '#ef4444',
            backgroundColor: 'rgba(239, 68, 68, 0.08)',
            pointBackgroundColor: '#ef4444',
            pointBorderColor: '#ffffff',
            pointBorderWidth: 2,
            pointRadius: (ctx) => {
              const val = ctx.raw;
              return val > 0 ? 6 : (series.evolucao.labels.length > 25 ? 2 : 4);
            },
            pointHoverRadius: 8.5,
            borderWidth: 2.5,
            borderDash: [5, 4],
            tension: 0.25,
            yAxisID: 'y',
            order: 2
          },
          {
            type: 'bar',
            label: series.evolucao.isDaily ? 'Atendimentos por Dia' : 'Atendimentos por Mês',
            data: series.evolucao.values,
            backgroundColor: 'rgba(59, 130, 246, 0.8)',
            hoverBackgroundColor: 'rgba(59, 130, 246, 0.95)',
            borderColor: '#3b82f6',
            borderWidth: 1.5,
            borderRadius: 4,
            yAxisID: 'y',
            order: 3
          }
        ]
      },
      options: {
        ...defaults,
        plugins: {
          ...defaults.plugins,
          legend: {
            display: true,
            position: 'top',
            labels: {
              font: { family: 'Inter', size: 11, weight: '600' },
              padding: 12,
              usePointStyle: true
            }
          },
          tooltip: {
            ...defaults.plugins.tooltip,
            callbacks: {
              title: function(items) {
                if (!items || !items.length) return '';
                const raw = items[0].label;
                if (Array.isArray(raw)) {
                  return `${raw[0]} de ${raw[1]}`;
                }
                if (series.evolucao.drillMonth) {
                  const [y, m] = series.evolucao.drillMonth.split('-');
                  const mesNome = mesesNomesPt[m] || m;
                  return `${raw} • ${mesNome} de ${y}`;
                }
                return raw;
              },
              label: function(context) {
                if (context.dataset.label && context.dataset.label.includes('SLA')) {
                  return `SLA Médio: ${Math.round(Number(context.raw))} dias`;
                }
                if (context.dataset.label && context.dataset.label.includes('Backlog')) {
                  const pts = pendentesPontosData ? pendentesPontosData[context.dataIndex] : context.raw;
                  if (context.raw === 0) {
                    return `Backlog Pendente: 0 ordens (100% concluído no prazo)`;
                  }
                  return `Backlog Pendente: ${context.raw} ordem${context.raw !== 1 ? 'ns' : ''} (${pts} ponto${pts !== 1 ? 's físicos' : ' físico'})`;
                }
                return `${context.dataset.label}: ${Number(context.raw).toLocaleString('pt-BR')} OS`;
              },
              afterBody: function(items) {
                if (!series.evolucao.isDaily) {
                  return ['', 'Dica: Clique na barra para descer o nível (Power BI)'];
                }
                return [];
              }
            }
          }
        },
        onClick: function(event, elements) {
          if (!elements || elements.length === 0) return;
          if (!series.evolucao.isDaily) {
            const idx = elements[0].index;
            const monthKey = series.evolucao.rawKeys ? series.evolucao.rawKeys[idx] : null;
            if (monthKey && monthKey.includes('-')) {
              evolucaoDrillMonth = monthKey;
              evolucaoGranularidade = 'dia';
              renderCharts();
              const [y, m] = monthKey.split('-');
              const mesNome = mesesNomesPt[m] || m;
              showToast(`Nível descido: detalhando ${mesNome} de ${y} dia a dia`, 'fa-magnifying-glass');
            }
          }
        },
        onHover: function(event, chartElement) {
          if (!series.evolucao.isDaily && chartElement.length > 0) {
            event.native.target.style.cursor = 'pointer';
          } else {
            event.native.target.style.cursor = 'default';
          }
        },
        scales: {
          x: {
            ...defaults.scales.x,
            ticks: {
              ...defaults.scales.x.ticks,
              font: { family: 'Inter', size: 11, weight: '600' },
              maxRotation: 0,
              autoSkip: series.evolucao.isDaily && series.evolucao.labels.length > 35
            }
          },
          y: {
            ...defaults.scales.y,
            type: 'linear',
            position: 'left',
            title: {
              display: true,
              text: 'Ordens (Atendidos & Backlog)',
              color: defaults.color,
              font: { family: 'Inter', size: 11, weight: '600' }
            },
            grace: '18%'
          },
          y1: {
            type: 'linear',
            position: 'right',
            min: 0,
            max: y1MaxMensal,
            title: {
              display: true,
              text: 'SLA (Dias)',
              color: '#10b981',
              font: { family: 'Inter', size: 11, weight: '600' }
            },
            grid: {
              drawOnChartArea: false
            },
            ticks: {
              color: '#10b981',
              font: { family: 'Inter', size: 11, weight: '600' },
              stepSize: y1MaxMensal > 10 ? 2 : 1,
              callback: function(value) {
                return value + 'd';
              }
            }
          }
        }
      }
    });
  }

  // 2. Gráfico de SLA (Doughnut / Pizza com Valores e Percentuais)
  const ctxSla = document.getElementById('chartSla');
  if (ctxSla) {
    if (chartSla) chartSla.destroy();
    const okFmt = Number(series.sla.ok).toLocaleString('pt-BR');
    const lateFmt = Number(series.sla.late).toLocaleString('pt-BR');
    chartSla = new Chart(ctxSla, {
      type: 'doughnut',
      data: {
        labels: [
          `No Prazo: ${okFmt} (${series.sla.taxa}%)`,
          `Com Atraso: ${lateFmt} (${(100 - series.sla.taxa).toFixed(1)}%)`
        ],
        datasets: [{
          data: [series.sla.ok, series.sla.late],
          backgroundColor: ['#10b981', '#ef4444'],
          borderWidth: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'bottom',
            labels: {
              padding: 14,
              font: { family: 'Inter', size: 12, weight: '600' }
            }
          }
        },
        cutout: '68%'
      }
    });
  }

  // 3. Gráfico de Produtividade Diária Recente (Combo Barras + Linha de Capacidade Média)
  const ctxUltimosDias = document.getElementById('chartUltimosDias');
  if (ctxUltimosDias && series.ultimosDias && series.ultimosDias.labels.length > 0) {
    if (chartUltimosDias) chartUltimosDias.destroy();

    const mediaCapacidade = Math.round(series.ultimosDias.media || 15);
    const mediaLine = series.ultimosDias.values.map(() => mediaCapacidade);
    const elSubProd = document.getElementById('subtitulo-chart-ultimos-dias');
    if (elSubProd) {
      elSubProd.textContent = `Oscilação diária de atendimento vs Linha de Capacidade Média (${mediaCapacidade}/dia)`;
    }

    chartUltimosDias = new Chart(ctxUltimosDias, {
      type: 'bar',
      data: {
        labels: series.ultimosDias.labels,
        datasets: [
          {
            type: 'line',
            label: `Capacidade Média (${mediaCapacidade}/dia)`,
            data: mediaLine,
            borderColor: '#f59e0b',
            borderWidth: 2,
            borderDash: [5, 5],
            pointRadius: 0,
            pointHoverRadius: 4,
            fill: false,
            tension: 0,
            order: 1
          },
          {
            type: 'bar',
            label: 'Ordens Concluídas / Dia',
            data: series.ultimosDias.values,
            backgroundColor: 'rgba(59, 130, 246, 0.75)',
            borderColor: '#3b82f6',
            borderWidth: 1.5,
            borderRadius: 4,
            order: 2
          }
        ]
      },
      options: {
        ...defaults,
        plugins: {
          ...defaults.plugins,
          legend: {
            display: true,
            position: 'top',
            labels: {
              font: { family: 'Inter', size: 11, weight: '600' },
              padding: 10,
              boxWidth: 20
            }
          },
          tooltip: {
            ...defaults.plugins.tooltip,
            callbacks: {
              afterLabel: function(context) {
                if (context.dataset.type === 'bar') {
                  const val = context.raw;
                  const diff = Math.round(val - mediaCapacidade);
                  return diff >= 0 ? `+${diff} acima da meta` : `${diff} abaixo da meta`;
                }
                return '';
              }
            }
          }
        },
        scales: {
          ...defaults.scales,
          y: {
            ...defaults.scales.y,
            grace: '18%'
          },
          x: {
            ...defaults.scales.x,
            ticks: {
              ...defaults.scales.x.ticks,
              maxRotation: 45,
              minRotation: 30,
              font: { size: 10 }
            }
          }
        }
      }
    });
  }

  // 4. Gráfico de Equipes (Barras Horizontais com Rótulos)
  const ctxEquipes = document.getElementById('chartEquipes');
  if (ctxEquipes) {
    if (chartEquipes) chartEquipes.destroy();
    chartEquipes = new Chart(ctxEquipes, {
      type: 'bar',
      data: {
        labels: series.equipes.labels,
        datasets: [{
          label: 'Atendimentos no Período',
          data: series.equipes.values,
          backgroundColor: ['#3b82f6', '#6366f1', '#8b5cf6', '#ec4899', '#14b8a6'],
          borderRadius: 6
        }]
      },
      options: {
        ...defaults,
        indexAxis: 'y',
        plugins: {
          ...defaults.plugins,
          equipeStats: series.equipes.stats || {},
          tooltip: {
            ...defaults.plugins.tooltip,
            callbacks: {
              afterLabel: function(context) {
                const eqName = context.label;
                const stats = context.chart.options?.plugins?.equipeStats?.[eqName];
                if (stats) {
                  const comRec = stats.noPrazo + stats.atrasados;
                  const slaDias = stats.countDias > 0 ? Math.round(stats.somaDias / stats.countDias) : 0;
                  return `SLA: ${slaDias} dias • ${stats.noPrazo} no prazo • ${stats.atrasados} atrasados • ${stats.ronda} ronda`;
                }
                return '';
              }
            }
          }
        },
        scales: {
          ...defaults.scales,
          x: {
            ...defaults.scales.x,
            grace: '28%'
          }
        }
      }
    });
  }

  // 4. Gráfico 1: SLA Médio (em Dias Inteiros) por Natureza de Ocorrência
  const ctxTiposSla = document.getElementById('chartTiposSla');
  if (ctxTiposSla) {
    if (chartTiposSla) chartTiposSla.destroy();

    const atend2026 = dashboardData.atendidos_2026 || [];
    const filtradosAtend = atend2026.filter(r => {
      if (!r.data_iso) return true;
      return r.data_iso >= dateFilterState.inicio && r.data_iso <= dateFilterState.fim;
    });

    const tiposMap = {};
    filtradosAtend.forEach(r => {
      const t = r.tipo || 'Outros';
      if (!tiposMap[t]) tiposMap[t] = { total: 0, somaDias: 0, countDias: 0 };
      tiposMap[t].total++;
      if (r.dias !== null && r.dias !== undefined) {
        tiposMap[t].somaDias += r.dias;
        tiposMap[t].countDias++;
      }
    });

    // Se poucos registros no filtro, recorre à série do dashboardData
    let tiposList = Object.keys(tiposMap)
      .filter(t => tiposMap[t].total >= 2)
      .map(t => {
        const item = tiposMap[t];
        const slaMedio = item.countDias > 0 ? (item.somaDias / item.countDias) : 0;
        return {
          tipo: t,
          total: item.total,
          sla: Math.round(slaMedio)
        };
      })
      .sort((a, b) => b.sla - a.sla)
      .slice(0, 8);

    const fallbackTipos = dashboardData.series && dashboardData.series.tipos_ocorrencia;
    if (tiposList.length === 0) {
      if (series.tipos && series.tipos.labels && series.tipos.labels.length > 0) {
        const slaMapRef = {};
        if (fallbackTipos && fallbackTipos.labels) {
          fallbackTipos.labels.forEach((lbl, idx) => {
            slaMapRef[lbl] = (fallbackTipos.sla_dias && fallbackTipos.sla_dias[idx]) || 2;
          });
        }
        tiposList = series.tipos.labels.map((lbl, idx) => ({
          tipo: lbl,
          total: series.tipos.values[idx] || 0,
          sla: slaMapRef[lbl] !== undefined ? slaMapRef[lbl] : 2
        })).sort((a, b) => b.sla - a.sla);
      } else if (fallbackTipos && fallbackTipos.labels) {
        tiposList = fallbackTipos.labels.map((lbl, idx) => ({
          tipo: lbl,
          total: fallbackTipos.values[idx] || 0,
          sla: Math.round((fallbackTipos.sla_dias && fallbackTipos.sla_dias[idx]) || 2)
        })).sort((a, b) => b.sla - a.sla);
      }
    }

    const labelsTipos = tiposList.map(item => item.tipo);
    const slaTipos = tiposList.map(item => item.sla);
    const extraCountsTipos = tiposList.map(item => `${item.total} OS`);

    const bgColorsTipos = slaTipos.map(sla => {
      if (sla > 3) return 'rgba(239, 68, 68, 0.75)';
      if (sla > 2) return 'rgba(245, 158, 11, 0.75)';
      return 'rgba(16, 185, 129, 0.75)';
    });

    const borderColorsTipos = slaTipos.map(sla => {
      if (sla > 3) return '#ef4444';
      if (sla > 2) return '#f59e0b';
      return '#10b981';
    });

    chartTiposSla = new Chart(ctxTiposSla, {
      type: 'bar',
      data: {
        labels: labelsTipos,
        datasets: [{
          label: 'SLA (Dias)',
          data: slaTipos,
          backgroundColor: bgColorsTipos,
          borderColor: borderColorsTipos,
          borderWidth: 1.5,
          borderRadius: 4
        }]
      },
      options: {
        ...defaults,
        indexAxis: 'y',
        plugins: {
          ...defaults.plugins,
          extraCounts: extraCountsTipos,
          legend: { display: false },
          tooltip: {
            ...defaults.plugins.tooltip,
            callbacks: {
              label: (ctx) => {
                const idx = ctx.dataIndex;
                const item = tiposList[idx];
                return [
                  `SLA: ${Math.round(item.sla)} dias`,
                  `Total de Chamados: ${item.total} ordens`
                ];
              }
            }
          }
        },
        scales: {
          ...defaults.scales,
          x: {
            ...defaults.scales.x,
            title: {
              display: true,
              text: 'SLA de Resolução (Dias)',
              color: defaults.color,
              font: { family: 'Inter', size: 10, weight: '600' }
            },
            grace: '25%'
          }
        }
      }
    });
  }

  // 4.2 Gráfico 2: SLA da Ocorrência por Bairro
  renderBairroOcorrenciaSlaChart();

  // 5. Gráfico de Bairros (Combo Barras de Atendimento + Linha de SLA no 2º Eixo)
  const ctxBairros = document.getElementById('chartBairros');
  if (ctxBairros) {
    if (chartBairros) chartBairros.destroy();

    const slaData = series.bairros.sla || series.bairros.values.map(() => 2.0);
    const maxSlaBairros = Math.max(...(slaData.length ? slaData : [5]), 4);
    const y1MaxBairros = Math.ceil(maxSlaBairros * 1.35);

    chartBairros = new Chart(ctxBairros, {
      type: 'bar',
      data: {
        labels: series.bairros.labels,
        datasets: [
          {
            type: 'line',
            label: 'SLA (Dias)',
            data: slaData,
            borderColor: '#10b981',
            backgroundColor: 'rgba(16, 185, 129, 0.1)',
            pointBackgroundColor: '#10b981',
            pointBorderColor: '#ffffff',
            pointBorderWidth: 2,
            pointRadius: 6,
            pointHoverRadius: 8,
            borderWidth: 3,
            tension: 0.35,
            yAxisID: 'y1',
            order: 1
          },
          {
            type: 'bar',
            label: 'Atendimentos por Bairro',
            data: series.bairros.values,
            backgroundColor: 'rgba(59, 130, 246, 0.85)',
            borderColor: '#3b82f6',
            borderWidth: 1.5,
            borderRadius: 5,
            yAxisID: 'y',
            order: 2
          }
        ]
      },
      options: {
        ...defaults,
        indexAxis: 'x', // Força barras verticais
        plugins: {
          ...defaults.plugins,
          legend: {
            display: true,
            position: 'top',
            labels: {
              font: { family: 'Inter', size: 11, weight: '600' },
              padding: 12,
              usePointStyle: true
            }
          },
          tooltip: {
            ...defaults.plugins.tooltip,
            callbacks: {
              label: function(context) {
                if (context.dataset.type === 'line') {
                  return `SLA: ${Math.round(Number(context.raw))} dias`;
                }
                return `Atendimentos Concluídos: ${Number(context.raw).toLocaleString('pt-BR')} ordens`;
              }
            }
          }
        },
        scales: {
          x: {
            ...defaults.scales.x,
            ticks: {
              ...defaults.scales.x.ticks,
              maxRotation: 30,
              minRotation: 15,
              autoSkip: false
            }
          },
          y: {
            ...defaults.scales.y,
            type: 'linear',
            position: 'left',
            title: {
              display: true,
              text: 'Atendimentos (OS)',
              color: defaults.color,
              font: { family: 'Inter', size: 11, weight: '600' }
            },
            grace: '18%'
          },
          y1: {
            type: 'linear',
            position: 'right',
            min: 0,
            max: y1MaxBairros,
            title: {
              display: true,
              text: 'SLA (Dias)',
              color: '#10b981',
              font: { family: 'Inter', size: 11, weight: '600' }
            },
            grid: {
              drawOnChartArea: false
            },
            ticks: {
              color: '#10b981',
              font: { family: 'Inter', size: 11, weight: '600' },
              stepSize: y1MaxBairros > 10 ? 2 : 1,
              callback: function(value) {
                return value + 'd';
              }
            }
          }
        }
      }
    });
  }
}

// ==========================================
// LINHA DO TEMPO: EVOLUÇÃO DOS CHAMADOS PENDENTES (TAB-BACKLOG)
// ==========================================
let timelineViewMode = 'marcos'; // 'marcos' definido como padrão oficial a pedido do usuário
let filtroGraficoData = null; // Filtro interativo disparado ao clicar nos pontos do gráfico

function renderChartEvolucaoPendentes() {
  const ctx = document.getElementById('chartEvolucaoPendentes');
  if (!ctx) return;
  if (chartEvolucaoPendentes) chartEvolucaoPendentes.destroy();

  const evol = dashboardData.evolucao_pendentes || {};
  const isMarcos = timelineViewMode === 'marcos' && evol.marcos;
  const currentEvol = isMarcos ? evol.marcos : evol;

  const labels = currentEvol.labels || ['18/08', '15/09', '22/09', '02/10', '06/10', '07/10', '08/10 (Atual)'];
  const pontos = currentEvol.pontos || [1, 22, 27, 28, 30, 32, 32];
  const chamados = currentEvol.chamados || [1, 5, 6, 7, 9, 11, 11];
  const vencidos = currentEvol.vencidos || [1, 5, 6, 6, 6, 6, 6];
  const atendidos = currentEvol.atendidos || (isMarcos ? [12, 24, 16, 2, 6, 10, 0] : [12, 9, 20, 5, 20, 18, 12, 21, 5, 28, 8, 20, 28, 25, 30, 38, 10, 24, 9, 16, 7, 3, 8, 19, 21, 8, 6, 2, 4, 6, 10, 0]);

  const setTVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) {
      if (typeof val === 'string' && val.includes('<')) {
        el.innerHTML = val;
      } else {
        el.textContent = val;
      }
    }
  };

  const kpis = dashboardData.kpis || {};
  const totPontos = kpis.total_pendentes_pontos !== undefined ? kpis.total_pendentes_pontos : 39;
  const totChamados = kpis.total_pendentes_chamados !== undefined ? kpis.total_pendentes_chamados : 30;
  const lista = dashboardData.pendentes_lista || [];
  const rondaPts = lista.filter(p => p.origem && p.origem.includes('Ronda')).reduce((a, c) => a + (c.pontos || 1), 0);
  const callPts = Math.max(0, totPontos - rondaPts);
  const rondaPct = totPontos > 0 ? Math.round((rondaPts / totPontos) * 100) : 0;
  const callPct = totPontos > 0 ? (100 - rondaPct) : 0;
  const totAtendidosPeriodo = evol.total_atendidos_periodo || atendidos.reduce((a, b) => a + b, 0);

  setTVal('tkpi-pontos-atual', `${totPontos} pts`);
  setTVal('tkpi-chamados-atual', `${totChamados} ordens ativas`);
  setTVal('tkpi-ronda-pts', `${rondaPts} pts (${rondaPct}%)`);
  setTVal('tkpi-callcenter-pts', `${callPts} pts (${callPct}%)`);
  setTVal('badge-backlog-versao', `<i class="fa-solid fa-folder-open"></i> Versão Ativa: ${evol.ultima_versao_arquivo || 'Última Planilha'}`);
  setTVal('tkpi-atendidos-periodo', `${totAtendidosPeriodo.toLocaleString('pt-BR')} ordens`);
  setTVal('tkpi-dias-operacao', `${labels.length} marcos/dias desde 18/08`);

  const defaults = getChartDefaults();

  chartEvolucaoPendentes = new Chart(ctx, {
    data: {
      labels: labels,
      datasets: [
        {
          type: 'bar',
          label: 'Chamados Atendidos no Dia (Concluídos)',
          data: atendidos,
          backgroundColor: 'rgba(16, 185, 129, 0.40)',
          hoverBackgroundColor: 'rgba(16, 185, 129, 0.75)',
          borderColor: '#10b981',
          borderWidth: 1.5,
          borderRadius: 4,
          order: 2,
          yAxisID: 'y'
        },
        {
          type: 'line',
          label: 'Pontos Físicos Pendentes (Acumulado)',
          data: pontos,
          borderColor: '#ef4444',
          backgroundColor: 'rgba(239, 68, 68, 0.08)',
          fill: true,
          borderWidth: 3,
          pointBackgroundColor: '#ef4444',
          pointBorderColor: '#ffffff',
          pointBorderWidth: 2,
          pointRadius: 4.5,
          pointHoverRadius: 8,
          tension: 0.25,
          order: 1,
          yAxisID: 'y'
        },
        {
          type: 'line',
          label: 'Ordens Pendentes em Aberto',
          data: chamados,
          borderColor: '#3b82f6',
          backgroundColor: 'transparent',
          borderWidth: 2,
          borderDash: [5, 4],
          pointBackgroundColor: '#3b82f6',
          pointBorderColor: '#ffffff',
          pointBorderWidth: 2,
          pointRadius: 4.5,
          pointHoverRadius: 8,
          tension: 0.25,
          order: 1,
          yAxisID: 'y'
        },
        {
          type: 'line',
          label: 'Ordens com SLA Vencido',
          data: vencidos,
          borderColor: '#f59e0b',
          backgroundColor: 'transparent',
          borderWidth: 2,
          pointBackgroundColor: '#f59e0b',
          pointBorderColor: '#ffffff',
          pointBorderWidth: 2,
          pointRadius: 4,
          pointHoverRadius: 7,
          tension: 0.25,
          order: 1,
          yAxisID: 'y'
        }
      ]
    },
    options: {
      ...defaults,
      onHover: (event, chartElement) => {
        const target = event.native ? event.native.target : event.chart?.canvas;
        if (target) {
          target.style.cursor = chartElement && chartElement.length > 0 ? 'pointer' : 'default';
        }
      },
      onClick: (event, elements, chart) => {
        // 1. Tenta clique exato no elemento (coluna de barra ou ponto de linha)
        let clickedElements = chart.getElementsAtEventForMode(event.native, 'point', { intersect: true }, false);
        
        // 2. Se não colidir exatamente, busca os elementos mais próximos
        if (!clickedElements || clickedElements.length === 0) {
          clickedElements = chart.getElementsAtEventForMode(event.native, 'nearest', { intersect: false }, true);
        }
        if (!clickedElements || clickedElements.length === 0) return;

        // Se houver mais de um elemento intersectado (ex: ponto sobre a barra), prioriza com precisão:
        let targetElement = clickedElements[0];
        if (clickedElements.length > 1) {
          const lineEl = clickedElements.find(el => el.datasetIndex !== 0);
          const barEl = clickedElements.find(el => el.datasetIndex === 0);
          if (lineEl && barEl) {
            const pt = lineEl.element;
            const mouseX = event.x !== undefined ? event.x : event.native?.offsetX;
            const mouseY = event.y !== undefined ? event.y : event.native?.offsetY;
            if (mouseX !== undefined && mouseY !== undefined && pt && pt.x !== undefined) {
              const dist = Math.hypot(mouseX - pt.x, mouseY - pt.y);
              if (dist <= ((pt.options && pt.options.radius) || 5) + 6) {
                targetElement = lineEl;
              } else {
                targetElement = barEl;
              }
            }
          }
        }

        const datasetIndex = targetElement.datasetIndex;
        const index = targetElement.index;
        const label = chart.data.labels[index];
        const dataset = chart.data.datasets[datasetIndex];

        handleBacklogChartClick(label, datasetIndex, dataset, index);
      },
      plugins: {
        ...defaults.plugins,
        legend: {
          display: true,
          position: 'top',
          labels: {
            font: { family: 'Inter', size: 11, weight: '600' },
            padding: 12,
            usePointStyle: true
          }
        },
        tooltip: {
          ...defaults.plugins.tooltip,
          callbacks: {
            label: function(context) {
              const val = context.raw;
              if (context.dataset.type === 'bar') {
                return `Atendidos Concluídos no Dia: ${val} ordem${val !== 1 ? 'ns' : ''}`;
              }
              if (context.datasetIndex === 1) {
                return `Passivo Físico Pendente: ${val} ponto${val !== 1 ? 's' : ''}`;
              }
              if (context.datasetIndex === 2) {
                return `Ordens Pendentes em Aberto: ${val} chamado${val !== 1 ? 's' : ''}`;
              }
              return `Ordens Vencidas: ${val} chamado${val !== 1 ? 's' : ''}`;
            },
            afterBody: function(contexts) {
              const first = contexts && contexts[0];
              if (first && first.dataset && first.dataset.type === 'bar') {
                return ['Dica: Clique nesta coluna para filtrar as ordens atendidas no dia'];
              }
              return ['Dica: Clique nesta linha para filtrar o passivo pendente no backlog'];
            }
          }
        }
      },
      scales: {
        ...defaults.scales,
        y: {
          ...defaults.scales.y,
          beginAtZero: true,
          grace: '15%',
          title: {
            display: true,
            text: 'Volume de Ordens & Pontos',
            color: defaults.color,
            font: { family: 'Inter', size: 11, weight: '600' }
          }
        }
      }
    }
  });
}

// Manipulador de Clique nos Pontos do Gráfico de Backlog
function handleBacklogChartClick(label, datasetIndex, dataset, index) {
  if (!label) return;
  const cleanDate = label.replace(/\s*\(Atual\)/i, '').trim();
  const parts = cleanDate.split('/');
  if (parts.length < 2) return;
  const targetIso = `2026-${parts[1].padStart(2, '0')}-${parts[0].padStart(2, '0')}`;

  const isColunaAtendidos = datasetIndex === 0;
  const isVencidosLine = datasetIndex === 3;
  const isPontosLine = datasetIndex === 1;

  const banner = document.getElementById('banner-filtro-grafico');
  const elData = document.getElementById('grafico-filter-data');
  const elDesc = document.getElementById('grafico-filter-desc');
  const btnAcum = document.getElementById('btn-filtro-acumulado');
  const btnDia = document.getElementById('btn-filtro-dia');
  const btnLimpar = document.getElementById('btn-limpar-filtro-grafico');
  const elHint = banner ? banner.querySelector('.grafico-filter-hint') : null;

  if (banner) banner.style.display = 'flex';
  if (elData) elData.textContent = cleanDate;

  // CASO 1: CLIQUE NA COLUNA DE ATENDIDOS (O que foi atendido / concluído)
  if (isColunaAtendidos) {
    const atendidosList = dashboardData.atendidos_2026 || [];
    const atendidosNoDia = atendidosList.filter(a => a.data_iso === targetIso);
    const atendidosAcum = atendidosList.filter(a => a.data_iso && a.data_iso <= targetIso);

    filtroGraficoData = {
      label: cleanDate,
      fullLabel: label,
      targetIso: targetIso,
      datasetIndex: 0,
      datasetName: dataset.label,
      tipo: 'atendidos',
      mode: 'dia' // Padrão da coluna é exatamente o que foi concluído nesta data
    };

    filtroAtual = 'todos';
    buscaAtual = '';
    const inputSearch = document.getElementById('input-busca-pendentes');
    if (inputSearch) inputSearch.value = '';

    if (elDesc) {
      elDesc.innerHTML = `<strong style="color: #10b981;">${atendidosNoDia.length} ordens concluídas</strong> nesta data (o que foi atendido)`;
    }
    if (elHint) {
      elHint.textContent = 'Exibindo a lista das ordens de serviço executadas e concluídas em campo nesta data:';
    }
    if (btnAcum) {
      btnAcum.style.display = 'inline-block';
      btnAcum.textContent = `Acumulado até ${cleanDate} (${atendidosAcum.length})`;
      btnAcum.classList.remove('active');
    }
    if (btnDia) {
      btnDia.style.display = 'inline-block';
      btnDia.textContent = `Concluídas em ${cleanDate} (${atendidosNoDia.length})`;
      btnDia.classList.add('active');
    }
    if (btnLimpar) {
      btnLimpar.innerHTML = '<i class="fa-solid fa-xmark"></i> Limpar Filtro (Voltar ao Backlog)';
    }

    renderPendentesTable();
    showToast(`Exibindo ${atendidosNoDia.length} atendimentos concluídos em ${cleanDate}`, 'fa-circle-check');
  } else {
    // CASO 2: CLIQUE NAS LINHAS DO BACKLOG PENDENTE
    const lista = dashboardData.pendentes_lista || [];
    const acumuladas = lista.filter(p => p.data_iso && p.data_iso <= targetIso).length;
    const noDia = lista.filter(p => p.data_iso && p.data_iso === targetIso).length;
    const pontosAcum = lista.filter(p => p.data_iso && p.data_iso <= targetIso).reduce((a, c) => a + (c.pontos || 1), 0);

    filtroGraficoData = {
      label: cleanDate,
      fullLabel: label,
      targetIso: targetIso,
      datasetIndex: datasetIndex,
      datasetName: dataset.label,
      tipo: 'pendentes',
      subtipo: isVencidosLine ? 'vencidos' : (isPontosLine ? 'pontos' : 'ordens'),
      mode: 'acumulado'
    };

    if (elDesc) {
      if (isVencidosLine) {
        const vencidasCount = lista.filter(p => p.data_iso && p.data_iso <= targetIso && p.is_vencido).length;
        elDesc.innerHTML = `<strong style="color: #ef4444;">${vencidasCount} ordens vencidas</strong> no backlog acumulado até esta data`;
      } else if (isPontosLine) {
        elDesc.innerHTML = `<strong style="color: #ef4444;">${pontosAcum} pontos físicos pendentes</strong> (${acumuladas} ordens no backlog acumulado)`;
      } else {
        elDesc.innerHTML = `<strong style="color: #3b82f6;">${acumuladas} ordens no backlog acumulado</strong> (${noDia} aberta nesta data)`;
      }
    }
    if (elHint) {
      elHint.textContent = 'Alternar visualização entre o passivo acumulado até a data ou ordens abertas no dia:';
    }
    if (btnAcum) {
      btnAcum.style.display = 'inline-block';
      btnAcum.textContent = `Acumulado até ${cleanDate} (${acumuladas})`;
      btnAcum.classList.add('active');
    }
    if (btnDia) {
      btnDia.style.display = 'inline-block';
      btnDia.textContent = `Abertas em ${cleanDate} (${noDia})`;
      btnDia.classList.remove('active');
    }
    if (btnLimpar) {
      btnLimpar.innerHTML = '<i class="fa-solid fa-xmark"></i> Limpar Filtro (Ver Todas)';
    }

    if (isVencidosLine) {
      filtroAtual = 'vencidos';
    } else {
      filtroAtual = 'todos';
    }

    renderPendentesTable();
    showToast(`Tabela de Backlog filtrada por ${cleanDate}: ${acumuladas} ordens exibidas`, 'fa-filter');
  }

  // Scroll suave até a tabela para visualizar imediatamente os chamados
  const tableCard = document.getElementById('tbody-pendentes')?.closest('.card');
  if (tableCard) {
    tableCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

// Configurações do Chart.js
function getChartDefaults() {
  const isLight = document.documentElement.getAttribute('data-theme') === 'light';
  const textColor = isLight ? '#475569' : '#94a3b8';
  const gridColor = isLight ? 'rgba(0, 0, 0, 0.06)' : 'rgba(255, 255, 255, 0.06)';

  return {
    responsive: true,
    maintainAspectRatio: false,
    color: textColor,
    plugins: {
      legend: {
        labels: {
          color: textColor,
          font: { family: 'Inter', size: 12, weight: '500' },
          boxWidth: 12,
          usePointStyle: true
        }
      },
      tooltip: {
        backgroundColor: isLight ? '#ffffff' : '#1e293b',
        titleColor: isLight ? '#0f172a' : '#ffffff',
        bodyColor: isLight ? '#334155' : '#cbd5e1',
        borderColor: isLight ? '#e2e8f0' : '#334155',
        borderWidth: 1,
        padding: 12,
        usePointStyle: true
      }
    },
    scales: {
      x: {
        grid: { color: gridColor },
        ticks: { color: textColor, font: { family: 'Inter', size: 11 } }
      },
      y: {
        grid: { color: gridColor },
        ticks: { color: textColor, font: { family: 'Inter', size: 11 } }
      }
    }
  };
}

// ==========================================
// SIMULADOR PREDITIVO & REGRESSÃO LINEAR
// ==========================================
function initSimulator() {
  const slider = document.getElementById('slider-capacidade');
  const badgeVal = document.getElementById('val-capacidade');
  const togglePontos = document.getElementById('toggle-pontos');
  const toggleChamados = document.getElementById('toggle-chamados');
  const inputMetaDias = document.getElementById('input-meta-dias');

  if (slider && badgeVal) {
    slider.value = simConfig.capacidadeDiaria;
    badgeVal.textContent = simConfig.capacidadeDiaria;

    slider.addEventListener('input', (e) => {
      simConfig.capacidadeDiaria = parseFloat(e.target.value);
      badgeVal.textContent = simConfig.capacidadeDiaria;
      updateSimulation();
    });
  }

  if (inputMetaDias) {
    inputMetaDias.addEventListener('input', (e) => {
      const dias = parseFloat(e.target.value);
      if (dias > 0) {
        simConfig.metaDiasDesejada = dias;
        const backlog = simConfig.unidade === 'pontos' ? dashboardData.kpis.total_pendentes_pontos : dashboardData.kpis.total_pendentes_chamados;
        const capNecessaria = Math.ceil(backlog / dias);
        const elRes = document.getElementById('calc-capacidade-necessaria');
        if (elRes) elRes.textContent = capNecessaria + '/dia';
      }
    });
  }

  if (togglePontos && toggleChamados) {
    togglePontos.addEventListener('click', () => {
      togglePontos.classList.add('active');
      toggleChamados.classList.remove('active');
      simConfig.unidade = 'pontos';
      updateSimulation();
    });

    toggleChamados.addEventListener('click', () => {
      toggleChamados.classList.add('active');
      togglePontos.classList.remove('active');
      simConfig.unidade = 'chamados';
      updateSimulation();
    });
  }

  updateSimulation();
}

function updateSimulation() {
  const k = dashboardData.kpis;
  const backlogInicial = simConfig.unidade === 'pontos' ? k.total_pendentes_pontos : k.total_pendentes_chamados;
  const capacidade = simConfig.capacidadeDiaria;

  const diasCorridos = Math.max(0.1, backlogInicial / capacidade);
  const diasUteis = Math.ceil(diasCorridos);

  const dataHoje = new Date();
  let dataFim = new Date(dataHoje);
  let diasAdicionados = 0;
  
  while (diasAdicionados < diasUteis) {
    dataFim.setDate(dataFim.getDate() + 1);
    const diaSemana = dataFim.getDay();
    if (diaSemana !== 0 && diaSemana !== 6) {
      diasAdicionados++;
    }
  }

  const dataFimStr = dataFim.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' });

  let riscoSlaCount = 0;
  let pontosAcumulados = 0;

  dashboardData.pendentes_lista.forEach(item => {
    if (!item.is_vencido) {
      const vol = simConfig.unidade === 'pontos' ? item.pontos : 1;
      pontosAcumulados += vol;
      const diaAtendimento = Math.ceil(pontosAcumulados / capacidade);
      if (diaAtendimento > item.dias_sla_restantes) {
        riscoSlaCount++;
      }
    }
  });

  const elDias = document.getElementById('sim-dias-zerar');
  const elData = document.getElementById('sim-data-zerar');
  const elVelocidade = document.getElementById('sim-velocidade-status');
  const elRisco = document.getElementById('sim-risco-sla');

  if (elDias) elDias.textContent = diasUteis + (diasUteis === 1 ? ' dia útil' : ' dias úteis');
  if (elData) elData.textContent = dataFimStr;
  
  if (elVelocidade) {
    if (diasUteis <= 2) {
      elVelocidade.innerHTML = '<span class="badge badge-success">Ritmo Excelente</span>';
    } else if (diasUteis <= 5) {
      elVelocidade.innerHTML = '<span class="badge badge-warning">Ritmo Moderado</span>';
    } else {
      elVelocidade.innerHTML = '<span class="badge badge-danger">Ritmo Insuficiente</span>';
    }
  }

  if (elRisco) {
    if (riscoSlaCount === 0) {
      elRisco.innerHTML = '<span class="text-success font-semibold">100% no prazo mantido</span>';
    } else {
      elRisco.innerHTML = `<span class="text-danger font-semibold">${riscoSlaCount} chamado(s) estourarão prazo</span>`;
    }
  }

  const elResCalc = document.getElementById('calc-capacidade-necessaria');
  if (elResCalc) {
    const meta = simConfig.metaDiasDesejada || 2;
    elResCalc.textContent = Math.ceil(backlogInicial / meta) + '/dia';
  }

  renderBurndownChart(backlogInicial, capacidade, diasUteis);
}

function renderBurndownChart(backlogInicial, queimaDiaria, diasParaZerar) {
  const ctx = document.getElementById('chartBurndown');
  if (!ctx) return;

  const diasMax = Math.max(7, Math.ceil(diasParaZerar) + 2);
  const labels = [];
  const dadosSimulado = [];
  const dadosMedia = [];
  const dadosAcelerado = [];
  const dadosReduzido = [];

  const mediaCapacidade = dashboardData.kpis.media_diaria_30d;

  for (let d = 0; d <= diasMax; d++) {
    labels.push(d === 0 ? 'Hoje (D+0)' : `D+${d}`);
    dadosSimulado.push(Math.max(0, Number((backlogInicial - (queimaDiaria * d)).toFixed(1))));
    dadosMedia.push(Math.max(0, Number((backlogInicial - (mediaCapacidade * d)).toFixed(1))));
    dadosAcelerado.push(Math.max(0, Number((backlogInicial - (25 * d)).toFixed(1))));
    dadosReduzido.push(Math.max(0, Number((backlogInicial - (5 * d)).toFixed(1))));
  }

  if (chartBurndown) {
    chartBurndown.destroy();
  }

  const defaults = getChartDefaults();

  chartBurndown = new Chart(ctx, {
    type: 'line',
    data: {
      labels: labels,
      datasets: [
        {
          label: `Cenário Simulado (${simConfig.capacidadeDiaria}/dia)`,
          data: dadosSimulado,
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.15)',
          borderWidth: 3,
          pointBackgroundColor: '#3b82f6',
          pointRadius: 5,
          fill: true
        },
        {
          label: `Média Atual (~15/dia)`,
          data: dadosMedia,
          borderColor: '#10b981',
          borderWidth: 2,
          borderDash: [5, 5],
          pointRadius: 0
        },
        {
          label: `Mutirão (25/dia)`,
          data: dadosAcelerado,
          borderColor: '#8b5cf6',
          borderWidth: 2,
          borderDash: [3, 3],
          pointRadius: 0
        },
        {
          label: `Reduzido (5/dia)`,
          data: dadosReduzido,
          borderColor: '#ef4444',
          borderWidth: 2,
          borderDash: [4, 4],
          pointRadius: 0
        }
      ]
    },
    options: {
      ...defaults,
      scales: {
        x: { ...defaults.scales.x, title: { display: true, text: 'Dias Úteis Futuros' } },
        y: {
          ...defaults.scales.y,
          title: { display: true, text: `${simConfig.unidade === 'pontos' ? 'Pontos' : 'Chamados'} Restantes` },
          min: 0
        }
      }
    }
  });
}

// ==========================================
// TABELA DE PENDENTES
// ==========================================
let filtroAtual = 'todos';
let buscaAtual = '';
let pendentesSort = {
  col: 'sla_dias',
  dir: 'desc'
};

function setupPendentesTableSort() {
  const thead = document.getElementById('thead-backlog-tabela');
  if (!thead || thead.dataset.sortInit) return;
  thead.dataset.sortInit = 'true';

  thead.addEventListener('click', (e) => {
    const th = e.target.closest('th.sortable');
    if (!th) return;
    const col = th.getAttribute('data-sort');
    if (!col) return;
    if (pendentesSort.col === col) {
      pendentesSort.dir = pendentesSort.dir === 'asc' ? 'desc' : 'asc';
    } else {
      pendentesSort.col = col;
      pendentesSort.dir = (col === 'sla_dias' || col === 'pontos') ? 'desc' : 'asc';
    }
    renderPendentesTable();
  });
}

function updateFilterButtonsForAtendidos(atendidosList, targetIso, mode) {
  const subset = atendidosList.filter(a => {
    if (mode === 'dia') return a.data_iso === targetIso;
    return a.data_iso && a.data_iso <= targetIso;
  });
  const tot = subset.length;
  const noPrazo = subset.filter(a => a.sla === 'No Prazo').length;
  const atrasados = subset.filter(a => a.sla === 'Atrasado').length;
  const ronda = subset.filter(a => (a.origem && a.origem.includes('Ronda')) || a.sla === 'Ronda').length;
  const callcenter = subset.filter(a => (!a.origem || !a.origem.includes('Ronda')) && a.sla !== 'Ronda').length;

  const btnTodos = document.querySelector('.filter-btn[data-filter="todos"]');
  const btnVenc = document.querySelector('.filter-btn[data-filter="vencidos"]');
  const btnPrazo = document.querySelector('.filter-btn[data-filter="no_prazo"]');
  const btnRonda = document.querySelector('.filter-btn[data-filter="ronda"]');
  const btnCall = document.querySelector('.filter-btn[data-filter="callcenter"]');

  if (btnTodos) btnTodos.textContent = `Todos (${tot})`;
  if (btnVenc) btnVenc.textContent = `Atrasados (${atrasados})`;
  if (btnPrazo) btnPrazo.textContent = `No Prazo (${noPrazo})`;
  if (btnRonda) btnRonda.textContent = `Ronda (${ronda})`;
  if (btnCall) btnCall.textContent = `Call Center (${callcenter})`;
}

function updateFilterButtonsForPendentes() {
  const lista = dashboardData.pendentes_lista || [];
  const tot = lista.length;
  const venc = lista.filter(p => p.is_vencido).length;
  const prazo = lista.filter(p => !p.is_vencido).length;
  const rondaPts = lista.filter(p => p.origem && p.origem.includes('Ronda')).reduce((a, c) => a + (c.pontos || 1), 0);
  const callPts = lista.filter(p => !p.origem || !p.origem.includes('Ronda')).reduce((a, c) => a + (c.pontos || 1), 0);

  const btnTodos = document.querySelector('.filter-btn[data-filter="todos"]');
  const btnVenc = document.querySelector('.filter-btn[data-filter="vencidos"]');
  const btnPrazo = document.querySelector('.filter-btn[data-filter="no_prazo"]');
  const btnRonda = document.querySelector('.filter-btn[data-filter="ronda"]');
  const btnCall = document.querySelector('.filter-btn[data-filter="callcenter"]');

  if (btnTodos) btnTodos.textContent = `Todos (${tot})`;
  if (btnVenc) btnVenc.textContent = `Vencidos (${venc})`;
  if (btnPrazo) btnPrazo.textContent = `No Prazo (${prazo})`;
  if (btnRonda) btnRonda.textContent = `Ronda (${rondaPts} pts)`;
  if (btnCall) btnCall.textContent = `Call Center (${callPts} pts)`;

  const badgeBacklog = document.getElementById('badge-backlog-count');
  if (badgeBacklog) badgeBacklog.textContent = tot;

  updateDiagnosticoRonda();
}

function updateDiagnosticoRonda() {
  const lista = dashboardData.pendentes_lista || [];
  const tot = lista.length;
  const ronda = lista.filter(p => (p.origem || '').toLowerCase().includes('ronda'));
  const rondaPts = ronda.reduce((a, c) => a + (c.pontos || 1), 0);
  const rondaVenc = ronda.filter(p => p.is_vencido);
  const rondaVencPts = rondaVenc.reduce((a, c) => a + (c.pontos || 1), 0);

  const call = lista.filter(p => !(p.origem || '').toLowerCase().includes('ronda'));
  const callPts = call.reduce((a, c) => a + (c.pontos || 1), 0);
  const callVenc = call.filter(p => p.is_vencido);
  const callVencPts = callVenc.reduce((a, c) => a + (c.pontos || 1), 0);

  const badgeEl = document.getElementById('diag-ronda-badge') || document.querySelector('.insight-summary-badge');
  if (badgeEl) {
    badgeEl.textContent = `${rondaVenc.length} ordens vencidas (${rondaVencPts} pts) na Ronda`;
  }

  const contentEl = document.getElementById('diag-ronda-content') || document.querySelector('.insight-accordion-content');
  if (contentEl) {
    contentEl.innerHTML = `
      Dos <strong>${tot} chamados pendentes</strong>, existe uma divisão nítida na operação:<br>
      &bull; <strong>Call Center (Munícipes):</strong> ${call.length} chamados (${callPts} pontos) &rarr; <strong>${callVenc.length === 0 ? '100% estão dentro do SLA' : `${callVenc.length} vencidos`}</strong>. A equipe atende a população rigorosamente no prazo!<br>
      &bull; <strong>Ronda Própria (Inspeção Técnica Interna):</strong> ${ronda.length} chamados (${rondaPts} pontos) &rarr; <strong>${rondaVenc.length} ordens estão com SLA vencido (${rondaVencPts} pontos)</strong>. Os chamados da ronda técnica concentram todo o passivo em atraso nos bairros.
    `;
  }
}

function renderPendentesTable() {
  const tbody = document.getElementById('tbody-pendentes');
  if (!tbody) return;

  tbody.innerHTML = '';

  const thead = document.getElementById('thead-backlog-tabela');
  const titleEl = document.getElementById('titulo-tabela-backlog');
  const totalEl = document.getElementById('table-total-count');

  setupPendentesTableSort();

  const getThSort = (col, label, title, icon = '') => {
    const isActive = pendentesSort.col === col;
    const iconDir = isActive ? (pendentesSort.dir === 'asc' ? '▲' : '▼') : '↕';
    const cls = `sortable ${isActive ? `active-sort ${pendentesSort.dir}` : ''}`;
    const style = isActive && col === 'sla_dias' ? 'style="background: rgba(16, 185, 129, 0.08); color: #10b981;"' : '';
    return `<th data-sort="${col}" class="${cls}" ${style} title="${title}">${icon}${label} <span class="sort-icon">${iconDir}</span></th>`;
  };

  // =========================================================================
  // CASO 1: VISUALIZANDO ATENDIMENTOS REALIZADOS (Clique na Coluna de Atendidos)
  // =========================================================================
  if (filtroGraficoData && filtroGraficoData.tipo === 'atendidos') {
    if (thead) {
      thead.innerHTML = `
        <tr>
          ${getThSort('os', 'OS / Protocolo', 'Ordenar por OS')}
          ${getThSort('dt_fim', 'Data Conclusão', 'Ordenar por Data de Conclusão')}
          ${getThSort('origem', 'Origem', 'Ordenar por Origem')}
          ${getThSort('eq', 'Equipe', 'Ordenar por Equipe')}
          ${getThSort('bairro', 'Bairro(s)', 'Ordenar por Bairro')}
          ${getThSort('tipo', 'Tipo de Serviço', 'Ordenar por Tipo')}
          ${getThSort('sla_dias', 'SLA', 'SLA em dias: prazo de resolução (Data Conclusão - Data Reclamação)', '<i class="fa-solid fa-stopwatch" style="margin-right: 4px;"></i>')}
          ${getThSort('sla_status', 'Status SLA', 'Ordenar por Status SLA')}
          ${getThSort('horas', 'Tempo Resolução', 'Tempo de Resolução')}
        </tr>
      `;
    }
    if (titleEl) {
      const modeTxt = filtroGraficoData.mode === 'acumulado' ? `Acumuladas até ${filtroGraficoData.label}` : `Concluídas em ${filtroGraficoData.label}`;
      titleEl.textContent = `Ordens de Serviço ${modeTxt} (Atendimentos Concluídos)`;
    }

    const atendidosList = dashboardData.atendidos_2026 || [];
    updateFilterButtonsForAtendidos(atendidosList, filtroGraficoData.targetIso, filtroGraficoData.mode);

    const filtrados = atendidosList.filter(item => {
      if (filtroGraficoData.mode === 'dia') {
        if (item.data_iso !== filtroGraficoData.targetIso) return false;
      } else {
        if (item.data_iso && item.data_iso > filtroGraficoData.targetIso) return false;
      }

      if (filtroAtual === 'vencidos' && item.sla !== 'Atrasado') return false;
      if (filtroAtual === 'no_prazo' && item.sla !== 'No Prazo') return false;
      if (filtroAtual === 'ronda' && !item.origem.includes('Ronda') && item.sla !== 'Ronda') return false;
      if (filtroAtual === 'callcenter' && (item.origem.includes('Ronda') || item.sla === 'Ronda')) return false;

      if (buscaAtual) {
        const q = buscaAtual.toLowerCase();
        const match = String(item.os).toLowerCase().includes(q) ||
                      (item.proto && item.proto.toLowerCase().includes(q)) ||
                      (item.bairro && item.bairro.toLowerCase().includes(q)) ||
                      (item.eq && item.eq.toLowerCase().includes(q)) ||
                      (item.tipo && item.tipo.toLowerCase().includes(q)) ||
                      (item.solucao && item.solucao.toLowerCase().includes(q)) ||
                      (item.origem && item.origem.toLowerCase().includes(q));
        if (!match) return false;
      }
      return true;
    });

    filtrados.sort((a, b) => {
      const col = pendentesSort.col;
      const dir = pendentesSort.dir === 'asc' ? 1 : -1;
      if (col === 'sla_dias') {
        const valA = (a.dias !== null && a.dias !== undefined && !isNaN(a.dias)) ? Number(a.dias) : -999;
        const valB = (b.dias !== null && b.dias !== undefined && !isNaN(b.dias)) ? Number(b.dias) : -999;
        return (valA - valB) * dir;
      }
      if (col === 'os') return (Number(a.os || 0) - Number(b.os || 0)) * dir;
      if (col === 'dt_fim') return ((a.data_iso || '')).localeCompare(b.data_iso || '') * dir;
      if (col === 'horas') return (Number(a.horas || 0) - Number(b.horas || 0)) * dir;
      if (col === 'sla_status') return ((a.sla || '')).localeCompare(b.sla || '') * dir;
      const valA = (a[col] || '').toString().toLowerCase();
      const valB = (b[col] || '').toString().toLowerCase();
      return valA.localeCompare(valB) * dir;
    });

    if (totalEl) {
      const modeTxt = filtroGraficoData.mode === 'acumulado' ? 'acumuladas até' : 'concluídas em';
      totalEl.textContent = `${filtrados.length} ordens de serviço ${modeTxt} ${filtroGraficoData.label}`;
    }

    if (filtrados.length === 0) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding: 32px; color: var(--text-dim);">Nenhuma ordem concluída encontrada com os filtros selecionados.</td></tr>`;
      return;
    }

    filtrados.forEach(item => {
      const tr = document.createElement('tr');
      const badgeSla = item.sla === 'No Prazo'
        ? '<span class="badge badge-success">No Prazo</span>'
        : (item.sla === 'Atrasado'
          ? '<span class="badge badge-danger">Atrasado</span>'
          : '<span class="badge badge-warning">Ronda</span>');
      
      const badgeOrigem = item.origem && item.origem.includes('Ronda')
        ? '<span class="badge badge-warning">Ronda Interna</span>'
        : (item.origem && item.origem.includes('App')
          ? '<span class="badge badge-info">App</span>'
          : '<span class="badge badge-info">Call Center</span>');

      const eqBadge = `<span class="badge" style="background: rgba(59, 130, 246, 0.12); color: #3b82f6; font-weight: 600;">${item.eq || 'Sem Equipe'}</span>`;

      const osProto = item.proto
        ? `<strong>${item.os}</strong><span style="display:block; font-size:0.75rem; color:var(--text-dim);">${item.proto}</span>`
        : `<strong>${item.os}</strong>`;

      const dVal = (item.dias !== null && item.dias !== undefined && !isNaN(item.dias)) ? Math.round(Number(item.dias)) : null;
      let badgeSlaKpi = '';
      if (dVal !== null) {
        if (dVal <= 1) {
          badgeSlaKpi = `<span class="tma-badge tma-badge-quick" title="SLA: Resolução em ${dVal}d"><i class="fa-solid fa-bolt"></i> ${dVal}d</span>`;
        } else if (dVal <= 3) {
          badgeSlaKpi = `<span class="tma-badge tma-badge-ontime" title="SLA: Resolução em ${dVal}d"><i class="fa-solid fa-stopwatch"></i> ${dVal}d</span>`;
        } else if (dVal <= 7) {
          badgeSlaKpi = `<span class="tma-badge tma-badge-warning" title="SLA: Resolução em ${dVal}d"><i class="fa-solid fa-triangle-exclamation"></i> ${dVal}d</span>`;
        } else {
          badgeSlaKpi = `<span class="tma-badge tma-badge-danger" title="SLA: Resolução em ${dVal}d (Acima da meta de 7d)"><i class="fa-solid fa-circle-exclamation"></i> ${dVal}d</span>`;
        }
      } else {
        badgeSlaKpi = `<span class="badge badge-secondary" title="Atendimento de Ronda Interna"><i class="fa-solid fa-shield-halved"></i> Ronda</span>`;
      }

      const tempoSla = (item.dias !== null && item.dias !== undefined && !isNaN(item.dias))
        ? `${Math.round(Number(item.dias))} dias`
        : (item.sla === 'Ronda' ? '<span style="color:var(--text-dim);">Ronda</span>' : '-');

      tr.innerHTML = `
        <td style="font-weight: 700;">${osProto}</td>
        <td>${item.dt_fim || '-'}</td>
        <td>${badgeOrigem}</td>
        <td>${eqBadge}</td>
        <td>${item.bairro || '-'}</td>
        <td style="font-size: 0.85rem;">${item.tipo || item.solucao || 'Manutenção'}</td>
        <td style="white-space: nowrap;">${badgeSlaKpi}</td>
        <td>${badgeSla}</td>
        <td style="color: var(--text-dim); font-size: 0.85rem; font-weight: 600;">${tempoSla}</td>
      `;
      tbody.appendChild(tr);
    });
    return;
  }

  // =========================================================================
  // CASO 2: VISUALIZANDO BACKLOG DE PENDENTES (Padrão ou Clique em Linhas)
  // =========================================================================
  if (thead) {
    thead.innerHTML = `
      <tr>
        ${getThSort('proto', 'Protocolo', 'Ordenar por Protocolo')}
        ${getThSort('dt_sol', 'Data Abertura', 'Ordenar por Data de Abertura')}
        ${getThSort('origem', 'Origem', 'Ordenar por Origem')}
        ${getThSort('pontos', 'Pontos Físicos', 'Ordenar por Pontos Físicos')}
        ${getThSort('bairro', 'Bairro(s)', 'Ordenar por Bairro')}
        ${getThSort('solicitante', 'Solicitante', 'Ordenar por Solicitante')}
        ${getThSort('sla_dias', 'SLA', 'SLA em dias: atraso ou prazo restante vs meta de 7d', '<i class="fa-solid fa-stopwatch" style="margin-right: 4px;"></i>')}
        ${getThSort('sla_status', 'Status SLA', 'Ordenar por Status SLA')}
        ${getThSort('tempo_rest', 'Tempo Restante / Atraso', 'Tempo Restante ou Atraso')}
      </tr>
    `;
  }
  if (titleEl) {
    if (filtroGraficoData) {
      if (filtroGraficoData.subtipo === 'vencidos') {
        titleEl.textContent = `Ordens com SLA Vencido no Backlog (${filtroGraficoData.label})`;
      } else if (filtroGraficoData.subtipo === 'pontos') {
        titleEl.textContent = `Pontos Físicos Pendentes no Backlog (Até ${filtroGraficoData.label})`;
      } else {
        titleEl.textContent = `Ordens Pendentes em Aberto (Backlog até ${filtroGraficoData.label})`;
      }
    } else {
      titleEl.textContent = `Lista Completa de Solicitações Pendentes`;
    }
  }

  updateFilterButtonsForPendentes();

  const lista = dashboardData.pendentes_lista || [];
  const filtrados = lista.filter(item => {
    // 1. Filtro interativo disparado ao clicar nos pontos do gráfico da Linha do Tempo
    if (filtroGraficoData) {
      if (filtroGraficoData.mode === 'dia') {
        if (item.data_iso !== filtroGraficoData.targetIso) return false;
      } else {
        // modo acumulado: ordens abertas até a data do marco clicado
        if (item.data_iso && item.data_iso > filtroGraficoData.targetIso) return false;
      }
    }

    // 2. Filtro temporal para ordens solicitadas no período
    if (!isCurrentOrTotalPreset(dateFilterState.preset, dateFilterState.label)) {
      if (item.data_iso) {
        if (dateFilterState.inicio && item.data_iso < dateFilterState.inicio) return false;
        if (dateFilterState.fim && item.data_iso > dateFilterState.fim) return false;
      }
    }

    if (filtroAtual === 'vencidos' && !item.is_vencido) return false;
    if (filtroAtual === 'no_prazo' && item.is_vencido) return false;
    if (filtroAtual === 'ronda' && !item.origem.includes('Ronda')) return false;
    if (filtroAtual === 'callcenter' && !item.origem.includes('Call Center')) return false;

    if (buscaAtual) {
      const q = buscaAtual.toLowerCase();
      const match = item.protocolo.toLowerCase().includes(q) ||
                    item.bairro.toLowerCase().includes(q) ||
                    item.solicitante.toLowerCase().includes(q) ||
                    item.origem.toLowerCase().includes(q);
      if (!match) return false;
    }

    return true;
  });

  filtrados.sort((a, b) => {
    const col = pendentesSort.col;
    const dir = pendentesSort.dir === 'asc' ? 1 : -1;
    if (col === 'sla_dias') {
      const valA = a.is_vencido ? (a.dias_atraso || 0) : -(a.dias_sla_restantes !== undefined ? a.dias_sla_restantes : 0);
      const valB = b.is_vencido ? (b.dias_atraso || 0) : -(b.dias_sla_restantes !== undefined ? b.dias_sla_restantes : 0);
      return (valA - valB) * dir;
    }
    if (col === 'proto') return (a.protocolo || '').localeCompare(b.protocolo || '') * dir;
    if (col === 'dt_sol') return ((a.data_iso || '')).localeCompare(b.data_iso || '') * dir;
    if (col === 'pontos') return ((a.pontos || 1) - (b.pontos || 1)) * dir;
    if (col === 'bairro') return ((a.bairro || '')).localeCompare(b.bairro || '') * dir;
    if (col === 'origem') return ((a.origem || '')).localeCompare(b.origem || '') * dir;
    if (col === 'solicitante') return ((a.solicitante || '')).localeCompare(b.solicitante || '') * dir;
    if (col === 'sla_status') return ((a.is_vencido ? 1 : 0) - (b.is_vencido ? 1 : 0)) * dir;
    if (col === 'tempo_rest') return ((a.tempo_restante_texto || '')).localeCompare(b.tempo_restante_texto || '') * dir;
    return 0;
  });

  const totalElCount = document.getElementById('table-total-count');
  if (totalElCount) {
    if (filtroGraficoData) {
      const modeTxt = filtroGraficoData.mode === 'acumulado' ? 'acumuladas até' : 'abertas em';
      totalElCount.textContent = `${filtrados.length} ordens ${modeTxt} ${filtroGraficoData.label} (Filtro do Gráfico Ativo)`;
    } else if (!isCurrentOrTotalPreset(dateFilterState.preset, dateFilterState.label)) {
      totalElCount.textContent = `${filtrados.length} ordens no período (de ${lista.length} ativas)`;
    } else {
      totalElCount.textContent = `${filtrados.length} ordens exibidas`;
    }
  }

  if (filtrados.length === 0) {
    tbody.innerHTML = `<tr><td colspan="9" style="text-align:center; padding: 32px; color: var(--text-dim);">Nenhuma ordem pendente encontrada com os filtros selecionados.</td></tr>`;
    return;
  }

  filtrados.forEach(item => {
    const tr = document.createElement('tr');

    let badgeSlaKpi = '';
    if (item.is_vencido) {
      const d = item.dias_atraso || 0;
      badgeSlaKpi = `<span class="tma-badge tma-badge-danger" title="SLA Vencido: atraso de ${d} dias além do limite de 7d"><i class="fa-solid fa-triangle-exclamation"></i> ${d}d <small>(Atraso)</small></span>`;
    } else {
      const d = item.dias_sla_restantes !== undefined ? item.dias_sla_restantes : 0;
      badgeSlaKpi = `<span class="tma-badge tma-badge-ontime" title="SLA no Prazo: restam ${d} dias para o limite de 7d"><i class="fa-solid fa-clock"></i> ${d}d <small>(Restam)</small></span>`;
    }

    let badgeStatus = item.is_vencido
      ? `<span class="badge badge-danger">Vencido</span>`
      : `<span class="badge badge-success">No Prazo</span>`;

    let badgeOrigem = item.origem.includes('Ronda')
      ? `<span class="badge badge-warning">Ronda Própria</span>`
      : `<span class="badge badge-info">Call Center</span>`;

    let badgeAuditoria = item.alerta_auditoria
      ? `<span class="badge-exclusao" title="Detectado Exclusão: Essa solicitação não se enconta na base de itens pendentes e ela não foi migrada para para itens concluídos, o sistema mantém essa solicitação até ela entrar no status de concluído.">
          <span>Detectado Exclusão</span>
          <span class="badge-info-icon"><i class="fa-solid fa-circle-info"></i></span>
          <div class="badge-tooltip-popup">
            <strong><i class="fa-solid fa-circle-info"></i> Detectado Exclusão</strong>
            Essa solicitação não se enconta na base de itens pendentes e ela não foi migrada para para itens concluídos, o sistema mantém essa solicitação até ela entrar no status de concluído.
          </div>
        </span>`
      : '';

    tr.innerHTML = `
      <td style="font-weight: 700;">${item.protocolo}${badgeAuditoria}</td>
      <td>${item.data_solicitacao}</td>
      <td>${badgeOrigem}</td>
      <td><span class="badge badge-info" style="font-weight: 700;">${item.pontos} pt${item.pontos > 1 ? 's' : ''}</span></td>
      <td>${item.bairro}</td>
      <td>${item.solicitante}</td>
      <td style="white-space: nowrap;">${badgeSlaKpi}</td>
      <td>${badgeStatus}</td>
      <td style="color: var(--text-dim); font-size: 0.8rem;">${item.tempo_restante_texto}</td>
    `;

    tbody.appendChild(tr);
  });
}

// ==========================================
// ABA: GESTÃO DE LUMINÁRIAS LED
// ==========================================
function renderLuminariasTab() {
  const daily = (dashboardData && Array.isArray(dashboardData.luminarias_daily)) ? dashboardData.luminarias_daily : null;
  const elTbody = document.getElementById('tbody-luminarias-potencia');

  // Sem dados extraídos: NÃO exibir números inventados
  if (!daily) {
    if (elTbody) elTbody.innerHTML = '<tr><td colspan="4" class="lum-empty">Base sem dados de Materiais. Rode o atualizador (build_dashboard_data.py) para extrair as luminárias.</td></tr>';
    ['lum-kpi-total', 'lum-kpi-predom-pct', 'lum-kpi-atend', 'lum-kpi-aux'].forEach(id => { const el = document.getElementById(id); if (el) el.textContent = '—'; });
    return;
  }

  const ini = dateFilterState.inicio || '2026-01-01';
  const fim = dateFilterState.fim || '2099-12-31';
  const op = lumOpState || 'tudo';
  const opBuckets = op === 'tudo' ? ['i', 'm', 'r'] : [op];
  const opLabels = {
    tudo: 'total (instaladas, mantidas e removidas)',
    i: 'instaladas / trocadas',
    m: 'mantidas',
    r: 'removidas'
  };

  // 1. Agregação no período do filtro
  const porChave = {};
  let rel = 0, tg = 0, atend = 0, convencionais = 0, diasComDados = 0;
  daily.forEach(r => {
    if (r.d < ini || r.d > fim) return;
    diasComDados++;
    rel += r.rel || 0;
    tg += r.tg || 0;
    atend += op === 'tudo' ? (r.at_any || 0) : (r['at_' + op] || 0);
    opBuckets.forEach(b => {
      const obj = r[b] || {};
      for (const [k, v] of Object.entries(obj)) {
        if (k === 'CONV') { convencionais += v; continue; }
        porChave[k] = (porChave[k] || 0) + v;
      }
    });
  });

  // 2. Agrupa por potência, mantendo detalhamento por modelo
  const porPot = {};
  for (const [k, v] of Object.entries(porChave)) {
    const [pot, modelo] = k.split('|');
    const isProj = (modelo || '').startsWith('PROJETOR');
    const potKey = isProj ? `Projetor ${pot}` : `LED ${pot}`;
    if (!porPot[potKey]) porPot[potKey] = { potencia: potKey, watts: parseInt(pot, 10) || 0, isProj, qtd: 0, modelos: {} };
    porPot[potKey].qtd += v;
    const nomeModelo = isProj ? (modelo.replace('PROJETOR', '').trim() || 'Projetor') : modelo;
    porPot[potKey].modelos[nomeModelo] = (porPot[potKey].modelos[nomeModelo] || 0) + v;
  }
  const linhas = Object.values(porPot).sort((a, b) => b.qtd - a.qtd || a.watts - b.watts);
  const total = linhas.reduce((s, l) => s + l.qtd, 0);
  const fmtPct = (n) => (total > 0 ? (n / total * 100) : 0).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 1 }) + '%';
  const titleCase = (s) => String(s).toLowerCase().replace(/(^|\s|-)\S/g, c => c.toUpperCase()).replace(/\bAr-n\b/i, 'AR-N').replace(/\bIi\b/, 'II').replace(/\bPf\b/, 'PF');
  const palette = ['#0ea5e9', '#3b82f6', '#10b981', '#6366f1', '#f59e0b', '#ec4899', '#14b8a6', '#8b5cf6', '#f97316', '#84cc16', '#06b6d4', '#a855f7'];

  // 3. KPIs
  const setTxt = (id, txt) => { const el = document.getElementById(id); if (el) el.textContent = txt; };
  const periodoTxt = (dateFilterState.label && dateFilterState.label !== 'Personalizado')
    ? dateFilterState.label
    : `${ini.split('-').reverse().join('/')} a ${fim.split('-').reverse().join('/')}`;

  setTxt('lum-kpi-total', total.toLocaleString('pt-BR'));
  setTxt('lum-kpi-total-sub', `LED ${opLabels[op]} • ${periodoTxt}`);
  setTxt('badge-total-lum-table', `${total.toLocaleString('pt-BR')} unidades • ${periodoTxt}`);

  if (linhas.length > 0) {
    const lider = linhas[0];
    const modeloLider = Object.entries(lider.modelos).sort((a, b) => b[1] - a[1])[0];
    setTxt('lum-kpi-predom-pct', fmtPct(lider.qtd));
    setTxt('lum-kpi-predom-desc', `${lider.potencia} ${titleCase(modeloLider[0])} (${lider.qtd.toLocaleString('pt-BR')} un)`);
  } else {
    setTxt('lum-kpi-predom-pct', '—');
    setTxt('lum-kpi-predom-desc', 'Sem luminárias no período');
  }

  setTxt('lum-kpi-atend', atend.toLocaleString('pt-BR'));
  const totalAtendPeriodo = (dashboardData.daily_records || []).filter(r => r.d >= ini && r.d <= fim).reduce((s, r) => s + (r.tot || 0), 0);
  setTxt('lum-kpi-atend-sub', `de ${totalAtendPeriodo.toLocaleString('pt-BR')} atendimentos no período com luminária ${op === 'tudo' ? 'registrada' : opLabels[op]}`);

  // Contagem dinâmica de telegestão e relés do período
  const tgDailyList = (dashboardData && Array.isArray(dashboardData.telegestao_daily)) ? dashboardData.telegestao_daily : [];
  let tgInstPeriodo = 0, tgRemPeriodo = 0, relInstPeriodo = 0, relRemPeriodo = 0, tgTotalGeralPeriodo = 0;
  tgDailyList.forEach(r => {
    if (r.d < ini || r.d > fim) return;
    const i = r.i || {};
    const rem = r.r || {};
    const tgI = i['Módulo de Telegestão'] || 0;
    const tgR = rem['Módulo de Telegestão'] || 0;
    const relI = i['Relé Fotoelétrico'] || 0;
    const relR = rem['Relé Fotoelétrico'] || 0;
    const outrosI = (i['Base para Relé'] || 0) + (i['Relé Cego (Shorting Cap)'] || 0);
    const outrosR = (rem['Base para Relé'] || 0) + (rem['Relé Cego (Shorting Cap)'] || 0);
    tgInstPeriodo += tgI;
    tgRemPeriodo += tgR;
    relInstPeriodo += relI;
    relRemPeriodo += relR;
    tgTotalGeralPeriodo += tgI + tgR + relI + relR + outrosI + outrosR;
  });

  const totalAux = (tgInstPeriodo || tg) + (relInstPeriodo || rel);
  setTxt('lum-kpi-aux', totalAux.toLocaleString('pt-BR'));
  setTxt('lum-kpi-aux-desc', `${(relInstPeriodo || rel).toLocaleString('pt-BR')} relés e ${(tgInstPeriodo || tg).toLocaleString('pt-BR')} telegestões instalados`);

  const bLed = document.getElementById('badge-subtab-led');
  if (bLed) bLed.textContent = `${total.toLocaleString('pt-BR')} un`;
  const bTg = document.getElementById('badge-subtab-telegestao');
  if (bTg) bTg.textContent = `${tgTotalGeralPeriodo.toLocaleString('pt-BR')} un`;

  // 4. Barra segmentada
  const barContainer = document.getElementById('lum-bar-container');
  if (barContainer) {
    barContainer.innerHTML = total > 0 ? linhas.map((l, i) => {
      const pct = (l.qtd / total * 100);
      return `<div class="lum-bar-segment" style="width: ${pct.toFixed(2)}%; background: ${palette[i % palette.length]};" title="${escapeHtml(l.potencia)}: ${fmtPct(l.qtd)} (${l.qtd.toLocaleString('pt-BR')} un)"></div>`;
    }).join('') : '';
  }

  // 5. Tabela por potência (Linhas clicáveis para Drill-Down)
  if (elTbody) {
    if (linhas.length === 0) {
      elTbody.innerHTML = `<tr><td colspan="4" class="lum-empty">Nenhuma luminária ${opLabels[op]} registrada na coluna Materiais entre ${ini.split('-').reverse().join('/')} e ${fim.split('-').reverse().join('/')}.</td></tr>`;
    } else {
      elTbody.innerHTML = linhas.map((l, i) => {
        const modelos = Object.entries(l.modelos).sort((a, b) => b[1] - a[1]);
        const modelosTxt = modelos.map(([m, q]) => modelos.length > 1 ? `${titleCase(m)} (${q.toLocaleString('pt-BR')})` : titleCase(m)).join(' / ');
        const isSelected = (typeof lumDrillState !== 'undefined' && lumDrillState.activePot === l.potencia);
        return `
        <tr class="lum-pot-row ${isSelected ? 'selected' : ''}" data-pot="${escapeHtml(l.potencia)}" title="Clique para auditar as ordens de serviço e protocolos de ${escapeHtml(l.potencia)}" style="cursor: pointer;">
          <td>
            <span class="lum-dot" style="background:${palette[i % palette.length]}"></span>
            <span class="${i === 0 ? 'pot-tag lider' : 'pot-tag'}">${escapeHtml(l.potencia)}</span>
            <span class="lum-row-hint"><i class="fa-solid fa-arrow-down" style="font-size:0.68rem; margin-right:2px;"></i>ver ordens</span>
          </td>
          <td><span class="modelo-desc-text">${escapeHtml(modelosTxt)}${i === 0 ? ' <em class="lum-lider-tag">Líder</em>' : ''}</span></td>
          <td class="qtd-cell">${l.qtd.toLocaleString('pt-BR')}</td>
          <td class="pct-cell">${fmtPct(l.qtd)}</td>
        </tr>`;
      }).join('');

      elTbody.querySelectorAll('.lum-pot-row').forEach(tr => {
        tr.addEventListener('click', () => {
          const pot = tr.getAttribute('data-pot');
          if (typeof openLumDrillDown === 'function') {
            openLumDrillDown(pot);
          }
        });
      });
    }
  }

  // 6. Cards laterais calculados dos dados reais
  const cargaW = linhas.reduce((s, l) => s + l.watts * l.qtd, 0);
  const potMedia = total > 0 ? Math.round(cargaW / total) : 0;
  const top2 = linhas.slice(0, 2);
  const top2Pct = total > 0 ? Math.round(top2.reduce((s, l) => s + l.qtd, 0) / total * 100) : 0;
  const insights = [
    {
      titulo: 'Padronização de Estoque',
      texto: linhas.length
        ? `${top2.map(l => l.potencia).join(' e ')} concentram ${top2Pct}% das luminárias ${opLabels[op]} no período. Priorize esses lotes no almoxarifado.`
        : 'Sem movimentação de luminárias no período selecionado.',
      icone: 'fa-solid fa-box-archive', cor: 'blue'
    },
    {
      titulo: 'Rede de Telegestão',
      texto: `${(tgInstPeriodo || tg).toLocaleString('pt-BR')} módulos de telegestão e ${(relInstPeriodo || rel).toLocaleString('pt-BR')} relés fotoelétricos instalados/substituídos no período` + (relRemPeriodo > 0 ? ` (além de ${relRemPeriodo.toLocaleString('pt-BR')} relés removidos na modernização para telegestão).` : '.'),
      icone: 'fa-solid fa-wifi', cor: 'green'
    },
    {
      titulo: 'Carga e Eficiência',
      texto: total > 0
        ? `Potência média de ${potMedia} W por luminária • carga total de ${(cargaW / 1000).toLocaleString('pt-BR', { maximumFractionDigits: 1 })} kW.` + (op === 'r' && convencionais > 0 ? ` Além disso, ${convencionais.toLocaleString('pt-BR')} luminárias convencionais removidas.` : '')
        : 'Sem dados de potência no período.',
      icone: 'fa-solid fa-arrow-trend-up', cor: 'yellow'
    }
  ];
  const sideContainer = document.getElementById('lum-side-cards-container');
  if (sideContainer) {
    sideContainer.innerHTML = insights.map(item => `
        <div class="card luminarias-insight-card">
          <div class="lum-insight-icon-box ${item.cor}">
            <i class="${item.icone}"></i>
          </div>
          <div class="lum-insight-body">
            <h3 class="lum-insight-title">${escapeHtml(item.titulo)}</h3>
            <p class="lum-insight-text">${escapeHtml(item.texto)}</p>
          </div>
        </div>`).join('');
  }

  // 7. Rodapé de auditoria
  const meta = dashboardData.metadata || {};
  setTxt('lum-fonte-gerado', `Base: ${meta.atendidos_arquivo || 'planilha SGI'} • painel gerado em ${meta.gerado_em || '—'} • ${diasComDados} dias com registros no período.`);

  // 8. Se o Drill-Down estiver aberto ou iniciado, inicializa listeners e atualiza tabela
  if (typeof initLumDrillDownListeners === 'function') initLumDrillDownListeners();
  if (typeof lumDrillState !== 'undefined' && lumDrillState.activePot && typeof renderLumDrillDown === 'function') {
    renderLumDrillDown();
  }

  // 9. Inicializa sub-navegação Ativos (LED vs Telegestão)
  if (typeof initAtivosSubnav === 'function') initAtivosSubnav();
}

// Estado do seletor de operação da aba Luminárias
let lumOpState = 'tudo';
function initLuminariasOpToggle() {
  const wrap = document.getElementById('lum-op-toggle');
  if (!wrap || wrap.dataset.bound) return;
  wrap.dataset.bound = '1';
  wrap.querySelectorAll('.lum-op-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      wrap.querySelectorAll('.lum-op-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      lumOpState = btn.getAttribute('data-op') || 'tudo';
      renderLuminariasTab();
    });
  });
}

// ==========================================
// TABELA ANALÍTICA • EXPLORADOR DE ATENDIMENTOS & SLA
// ==========================================
let analiticoState = {
  search: '',
  mesFilter: 'todos',     // 'todos', '2026-10', '2026-09', etc.
  slaFilter: 'todos',     // 'todos', 'com_rec', 'no_prazo', 'atrasado', 'ronda'
  tmaFilter: 'todas',     // 'todas', 'rapido', 'padrao', 'limite', 'critico'
  equipeFilter: 'todas',  // 'todas' ou nome da equipe
  origemFilter: 'todas',  // 'todas', 'callcenter', 'ronda', 'app', 'internet', 'telegestao', 'chatbot'
  sortCol: 'dias',
  sortDir: 'desc',        // 'asc' ou 'desc'
  currentPage: 1,
  pageSize: 25,
  filteredData: []
};

function getAnaliticoFullList() {
  if (dashboardData.solicitacoes_full && dashboardData.solicitacoes_full.length > 0) {
    return dashboardData.solicitacoes_full;
  }
  // Fallback: unificar atendidos_2026 com pendentes_lista
  const atendidos = (dashboardData.atendidos_2026 || []).map(r => ({ ...r, is_pendente: false }));
  const pendentes = (dashboardData.pendentes_lista || []).map(p => {
    const isVenc = !!p.is_vencido;
    const solId = p.solicitacao || (p.protocolo ? p.protocolo.split('/')[0] : '');
    const alertaExclusao = !!p.alerta_auditoria;
    return {
      os: parseInt(solId) || solId,
      proto: p.protocolo || '',
      origem: p.origem || 'Ronda própria',
      dt_rec: p.data_solicitacao || '',
      dt_fim: '',
      data_iso: (p.data_solicitacao || '').slice(0, 10).split('/').reverse().join('-'),
      dias: isVenc ? (p.dias_atraso || 0) : (p.dias_sla_restantes || 0),
      horas: null,
      sla: alertaExclusao ? 'Detectado Exclusão' : (isVenc ? 'Atrasado' : 'No Prazo'),
      eq: p.atendente || 'Backlog / CCO',
      bairro: p.bairro || 'Barretos',
      tipo: p.tipo || 'Manutenção / Iluminação Pública',
      solucao: p.status || 'Em Atendimento',
      is_pendente: true,
      alerta_auditoria: alertaExclusao,
      audit_nota: p.audit_nota || '',
      pontos: p.pontos || 1,
      tempo_restante_texto: p.tempo_restante_texto || ''
    };
  });
  return [...atendidos, ...pendentes];
}

function initAnaliticoTable() {
  const lista = getAnaliticoFullList();

  // Preencher dropdown de equipes dinamicamente
  const selectEquipe = document.getElementById('filtro-analitico-equipe');
  if (selectEquipe) {
    const equipesSet = new Set();
    lista.forEach(r => {
      if (r.eq && r.eq !== 'Sem Equipe') equipesSet.add(r.eq);
    });
    const sortedEquipes = Array.from(equipesSet).sort();
    selectEquipe.innerHTML = '<option value="todas">Todas as Equipes</option>' +
      sortedEquipes.map(eq => `<option value="${escapeHtml(eq)}">${escapeHtml(eq)}</option>`).join('');

    selectEquipe.addEventListener('change', (e) => {
      analiticoState.equipeFilter = e.target.value;
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Busca textual com debounce
  const inputBusca = document.getElementById('busca-analitico');
  const btnLimparBusca = document.getElementById('btn-limpar-busca');
  if (inputBusca) {
    let debounceTimer = null;
    inputBusca.addEventListener('input', (e) => {
      clearTimeout(debounceTimer);
      const val = e.target.value;
      if (btnLimparBusca) btnLimparBusca.style.display = val ? 'block' : 'none';
      debounceTimer = setTimeout(() => {
        analiticoState.search = val.trim().toLowerCase();
        analiticoState.currentPage = 1;
        applyAnaliticoFilters();
      }, 150);
    });
  }

  if (btnLimparBusca && inputBusca) {
    btnLimparBusca.addEventListener('click', () => {
      inputBusca.value = '';
      btnLimparBusca.style.display = 'none';
      analiticoState.search = '';
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Select Mês
  const selectMes = document.getElementById('filtro-analitico-mes');
  if (selectMes) {
    selectMes.addEventListener('change', (e) => {
      analiticoState.mesFilter = e.target.value;
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Select SLA
  const selectSla = document.getElementById('filtro-analitico-sla');
  if (selectSla) {
    selectSla.addEventListener('change', (e) => {
      analiticoState.slaFilter = e.target.value;
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Select TMA
  const selectTma = document.getElementById('filtro-analitico-tma');
  if (selectTma) {
    selectTma.addEventListener('change', (e) => {
      analiticoState.tmaFilter = e.target.value;
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Select Origem
  const selectOrigem = document.getElementById('filtro-analitico-origem');
  if (selectOrigem) {
    selectOrigem.addEventListener('change', (e) => {
      analiticoState.origemFilter = e.target.value;
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  }

  // Botão Limpar Filtros
  const btnReset = document.getElementById('btn-reset-analitico');
  if (btnReset) {
    btnReset.addEventListener('click', () => {
      resetAnaliticoFilters();
    });
  }

  // Quick Chips
  const quickChips = document.querySelectorAll('.analitico-quick-chips .quick-chip');
  quickChips.forEach(chip => {
    chip.addEventListener('click', () => {
      quickChips.forEach(c => c.classList.remove('active'));
      chip.classList.add('active');

      if (chip.getAttribute('data-reset') === 'true') {
        resetAnaliticoFilters();
        return;
      }

      if (chip.hasAttribute('data-mes')) {
        const mesVal = chip.getAttribute('data-mes');
        analiticoState.mesFilter = mesVal;
        if (selectMes) selectMes.value = mesVal;
      }
      if (chip.hasAttribute('data-origem')) {
        const origVal = chip.getAttribute('data-origem');
        analiticoState.origemFilter = origVal;
        if (selectOrigem) selectOrigem.value = origVal;
      }
      if (chip.hasAttribute('data-sla')) {
        const slaVal = chip.getAttribute('data-sla');
        analiticoState.slaFilter = slaVal;
        if (selectSla) selectSla.value = slaVal;
      }
      if (chip.hasAttribute('data-tma')) {
        const tmaVal = chip.getAttribute('data-tma');
        analiticoState.tmaFilter = tmaVal;
        if (selectTma) selectTma.value = tmaVal;
      }
      analiticoState.currentPage = 1;
      applyAnaliticoFilters();
    });
  });

  // Linhas por página
  const selectPerPage = document.getElementById('analitico-per-page');
  if (selectPerPage) {
    selectPerPage.addEventListener('change', (e) => {
      analiticoState.pageSize = parseInt(e.target.value) || 25;
      analiticoState.currentPage = 1;
      renderAnaliticoTable();
    });
  }

  // Paginação
  const btnFirst = document.getElementById('analitico-first');
  const btnPrev = document.getElementById('analitico-prev');
  const btnNext = document.getElementById('analitico-next');
  const btnLast = document.getElementById('analitico-last');

  if (btnFirst) btnFirst.addEventListener('click', () => { analiticoState.currentPage = 1; renderAnaliticoTable(); });
  if (btnPrev) btnPrev.addEventListener('click', () => { if (analiticoState.currentPage > 1) { analiticoState.currentPage--; renderAnaliticoTable(); } });
  if (btnNext) btnNext.addEventListener('click', () => {
    const totalPages = Math.ceil(analiticoState.filteredData.length / analiticoState.pageSize) || 1;
    if (analiticoState.currentPage < totalPages) { analiticoState.currentPage++; renderAnaliticoTable(); }
  });
  if (btnLast) btnLast.addEventListener('click', () => {
    analiticoState.currentPage = Math.ceil(analiticoState.filteredData.length / analiticoState.pageSize) || 1;
    renderAnaliticoTable();
  });

  // Ordenação de colunas
  const headers = document.querySelectorAll('#tabela-analitico th.sortable');
  headers.forEach(th => {
    th.addEventListener('click', () => {
      const col = th.getAttribute('data-sort');
      if (analiticoState.sortCol === col) {
        analiticoState.sortDir = analiticoState.sortDir === 'asc' ? 'desc' : 'asc';
      } else {
        analiticoState.sortCol = col;
        analiticoState.sortDir = (col === 'dias' || col === 'os') ? 'desc' : 'asc';
      }

      headers.forEach(h => {
        h.classList.remove('active-sort', 'asc', 'desc');
        const icon = h.querySelector('.sort-icon');
        if (icon) icon.textContent = '↕';
      });

      th.classList.add('active-sort', analiticoState.sortDir);
      const activeIcon = th.querySelector('.sort-icon');
      if (activeIcon) activeIcon.textContent = analiticoState.sortDir === 'asc' ? '▲' : '▼';

      const sortLabels = {
        os: 'Ordem de Serviço',
        dt_rec: 'Data da Reclamação',
        dt_fim: 'Data de Conclusão',
        dias: 'SLA / Resolução (Dias)',
        sla: 'Status do SLA',
        eq: 'Equipe',
        bairro: 'Bairro'
      };
      const sortInfo = document.getElementById('analitico-sort-info');
      if (sortInfo) {
        sortInfo.textContent = `Ordenado por: ${sortLabels[col] || col} (${analiticoState.sortDir === 'asc' ? 'Menor p/ Maior' : 'Maior p/ Menor'})`;
      }

      sortAndRenderAnalitico();
    });
  });

  // Botão Exportar Excel
  const btnExport = document.getElementById('btn-exportar-analitico');
  if (btnExport) {
    btnExport.addEventListener('click', () => {
      exportarAnaliticoExcel();
    });
  }

  // Execução inicial
  applyAnaliticoFilters();
}

function resetAnaliticoFilters() {
  analiticoState.search = '';
  analiticoState.mesFilter = 'todos';
  analiticoState.slaFilter = 'todos';
  analiticoState.tmaFilter = 'todas';
  analiticoState.equipeFilter = 'todas';
  analiticoState.origemFilter = 'todas';
  analiticoState.currentPage = 1;

  const inputBusca = document.getElementById('busca-analitico');
  const btnLimpar = document.getElementById('btn-limpar-busca');
  const selectMes = document.getElementById('filtro-analitico-mes');
  const selectSla = document.getElementById('filtro-analitico-sla');
  const selectTma = document.getElementById('filtro-analitico-tma');
  const selectEquipe = document.getElementById('filtro-analitico-equipe');
  const selectOrigem = document.getElementById('filtro-analitico-origem');
  const quickChips = document.querySelectorAll('.analitico-quick-chips .quick-chip');

  if (inputBusca) inputBusca.value = '';
  if (btnLimpar) btnLimpar.style.display = 'none';
  if (selectMes) selectMes.value = 'todos';
  if (selectSla) selectSla.value = 'todos';
  if (selectTma) selectTma.value = 'todas';
  if (selectEquipe) selectEquipe.value = 'todas';
  if (selectOrigem) selectOrigem.value = 'todas';
  quickChips.forEach(c => c.classList.remove('active'));

  applyAnaliticoFilters();
}

function applyAnaliticoFilters() {
  const rawList = getAnaliticoFullList();
  const q = (analiticoState.search || '').trim().toLowerCase();
  const mesF = analiticoState.mesFilter || 'todos';
  const slaF = analiticoState.slaFilter;
  const tmaF = analiticoState.tmaFilter;
  const eqF = analiticoState.equipeFilter;
  const origF = analiticoState.origemFilter;

  // Filtragem
  const filtered = rawList.filter(r => {
    // 0. Filtro por Mês Específico (quando selecionado pelo usuário)
    if (mesF !== 'todos') {
      const parts = mesF.split('-');
      const yyyy = parts[0];
      const mm = parts[1];
      // Para chamados com Reclamação formal de munícipe, o mês da demanda é a Data da Reclamação
      let matchMes = false;
      if (r.dt_rec && r.dt_rec !== 'Ronda Interna' && !r.dt_rec.toLowerCase().includes('não informada')) {
        matchMes = r.dt_rec.includes(`/${mm}/${yyyy}`);
      } else {
        // Se for Ronda Interna sem munícipe, a referência é a data de conclusão/execução
        matchMes = (r.data_iso && r.data_iso.startsWith(mesF)) ||
                   (r.dt_fim && (r.dt_fim.includes(`/${mm}/${yyyy}`) || r.dt_fim.endsWith(`/${yyyy}`)));
      }
      if (!matchMes) return false;
    } else {
      // 0b. Filtro Temporal Global (dateFilterState)
      // Se o usuário digitou uma busca específica (ex: '1827690', número de OS ou texto),
      // ignoramos a restrição de data para garantir localização instantânea de qualquer chamado.
      if (!q && r.data_iso) {
        if (dateFilterState.inicio && r.data_iso < dateFilterState.inicio) return false;
        if (dateFilterState.fim && r.data_iso > dateFilterState.fim) return false;
      }
    }

    // 1. SLA Filter
    if (slaF === 'pendentes' && !r.is_pendente) return false;
    if (slaF === 'concluidos' && r.is_pendente) return false;
    if (slaF === 'exclusao' && (!r.is_pendente || !r.alerta_auditoria)) return false;
    if (slaF === 'com_rec' && (r.dias === null || r.dias === undefined || (r.origem && r.origem.toLowerCase().includes('ronda')))) return false;
    if (slaF === 'no_prazo' && r.sla !== 'No Prazo') return false;
    if (slaF === 'atrasado' && r.sla !== 'Atrasado') return false;
    if (slaF === 'ronda' && r.sla !== 'Ronda' && !(r.origem && r.origem.toLowerCase().includes('ronda'))) return false;

    // 2. TMA Filter
    if (tmaF === 'rapido') {
      if (r.dias === null || r.dias > 1.0) return false;
    } else if (tmaF === 'padrao') {
      if (r.dias === null || r.dias <= 1.0 || r.dias > 3.0) return false;
    } else if (tmaF === 'limite') {
      if (r.dias === null || r.dias <= 3.0 || r.dias > 7.0) return false;
    } else if (tmaF === 'critico') {
      if (r.dias === null || r.dias <= 7.0) return false;
    }

    // 3. Equipe Filter
    if (eqF !== 'todas' && r.eq !== eqF) return false;

    // 4. Origem Filter
    if (origF === 'callcenter') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('call center')) return false;
    } else if (origF === 'ronda') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('ronda')) return false;
    } else if (origF === 'app') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('app')) return false;
    } else if (origF === 'internet') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('internet')) return false;
    } else if (origF === 'telegestao') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('telegest')) return false;
    } else if (origF === 'chatbot') {
      const o = (r.origem || '').toLowerCase();
      if (!o.includes('chatbot')) return false;
    }

    // 5. Busca Textual Ampla
    if (q) {
      const match = String(r.os).toLowerCase().includes(q) ||
                    (r.proto && r.proto.toLowerCase().includes(q)) ||
                    (r.origem && r.origem.toLowerCase().includes(q)) ||
                    (r.bairro && r.bairro.toLowerCase().includes(q)) ||
                    (r.eq && r.eq.toLowerCase().includes(q)) ||
                    (r.tipo && r.tipo.toLowerCase().includes(q)) ||
                    (r.solucao && r.solucao.toLowerCase().includes(q)) ||
                    (r.dt_rec && r.dt_rec.toLowerCase().includes(q)) ||
                    (r.dt_fim && r.dt_fim.toLowerCase().includes(q)) ||
                    (r.sla && r.sla.toLowerCase().includes(q)) ||
                    (r.audit_nota && r.audit_nota.toLowerCase().includes(q));
      if (!match) return false;
    }

    return true;
  });

  analiticoState.filteredData = filtered;

  // Recalcular Mini-KPIs com base nos dados filtrados
  updateAnaliticoKPIs(filtered);

  // Ordenar e renderizar página
  sortAndRenderAnalitico();
}

function updateAnaliticoKPIs(filtered) {
  const total = filtered.length;
  const concluidosComDias = filtered.filter(r => !r.is_pendente && r.dias !== null && r.dias !== undefined);
  const noPrazo = filtered.filter(r => !r.is_pendente && r.sla === 'No Prazo').length;
  const atrasadas = filtered.filter(r => !r.is_pendente && r.sla === 'Atrasado').length;
  const rondas = filtered.filter(r => !r.is_pendente && (r.sla === 'Ronda' || ((r.origem || '').toLowerCase().includes('ronda') && (r.dias === null || r.dias === undefined)))).length;
  const pendentesTotal = filtered.filter(r => r.is_pendente).length;
  const pendentesAtrasadas = filtered.filter(r => r.is_pendente && (r.sla === 'Atrasado' || r.alerta_auditoria)).length;

  let tmaMedio = '-';
  let tmaHoras = '-';
  let tmaMediana = '-';
  let taxaSla = '-';

  if (concluidosComDias.length > 0) {
    const sumDias = concluidosComDias.reduce((acc, c) => acc + c.dias, 0);
    const sumHoras = concluidosComDias.reduce((acc, c) => acc + (c.horas || c.dias * 24), 0);
    const avgDias = sumDias / concluidosComDias.length;
    const avgHoras = sumHoras / concluidosComDias.length;

    const avgStr = (avgDias % 1 === 0 ? avgDias.toFixed(0) : avgDias.toFixed(1).replace('.', ','));
    tmaMedio = `${avgStr} dias`;
    tmaHoras = `~${Math.round(avgHoras)}h • Mediana: ${tmaMediana}`;

    // Mediana
    const sortedDias = concluidosComDias.map(c => c.dias).sort((a, b) => a - b);
    const mid = Math.floor(sortedDias.length / 2);
    const medVal = sortedDias.length % 2 !== 0 ? sortedDias[mid] : ((sortedDias[mid - 1] + sortedDias[mid]) / 2);
    const medValInt = Math.round(medVal);
    tmaMediana = medValInt + ' dia' + (medValInt !== 1 ? 's' : '');
  }

  if (noPrazo + atrasadas > 0) {
    const rate = (noPrazo / (noPrazo + atrasadas)) * 100;
    taxaSla = rate.toFixed(1) + '%';
  }

  const setEl = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setEl('analitico-kpi-total', total.toLocaleString('pt-BR'));
  setEl('analitico-kpi-tma', tmaMedio);
  setEl('analitico-kpi-horas', tmaHoras);
  setEl('analitico-kpi-mediana', tmaMediana);
  setEl('analitico-kpi-sla', taxaSla);
  setEl('analitico-kpi-noprazo', `${noPrazo.toLocaleString('pt-BR')} no prazo (≤ 7d)`);
  setEl('analitico-kpi-noprazo-count', noPrazo.toLocaleString('pt-BR'));
  setEl('analitico-kpi-atrasadas', (atrasadas + pendentesAtrasadas).toLocaleString('pt-BR'));
  setEl('analitico-kpi-ronda', rondas.toLocaleString('pt-BR'));

  const countEl = document.getElementById('analitico-table-count');
  if (countEl) countEl.textContent = total.toLocaleString('pt-BR');

  const badgeCount = document.getElementById('badge-analitico-count');
  if (badgeCount) badgeCount.textContent = `${total.toLocaleString('pt-BR')} ordens`;

  const badgeMetodologia = document.getElementById('badge-metodologia-sla');
  if (badgeMetodologia) {
    let metText = `${concluidosComDias.length.toLocaleString('pt-BR')} com chamado (Base do SLA) &bull; ${rondas.toLocaleString('pt-BR')} rondas`;
    if (pendentesTotal > 0) {
      metText += ` &bull; ${pendentesTotal.toLocaleString('pt-BR')} backlog em aberto`;
    }
    badgeMetodologia.innerHTML = metText;
  }

  const chipTotal = document.getElementById('analitico-chip-total');
  if (chipTotal) chipTotal.textContent = total.toLocaleString('pt-BR');

  const exclusaoTotal = filtered.filter(r => r.is_pendente && r.alerta_auditoria).length;
  setEl('analitico-chip-backlog', pendentesTotal.toLocaleString('pt-BR'));
  setEl('analitico-chip-exclusao', exclusaoTotal.toLocaleString('pt-BR'));
}

function sortAndRenderAnalitico() {
  const col = analiticoState.sortCol;
  const dir = analiticoState.sortDir === 'asc' ? 1 : -1;

  const parseBrDateToIso = (str) => {
    if (!str) return '';
    const parts = str.trim().split(' ');
    const dParts = parts[0].split('/');
    if (dParts.length === 3) {
      const yyyy = dParts[2];
      const mm = dParts[1].padStart(2, '0');
      const dd = dParts[0].padStart(2, '0');
      return `${yyyy}-${mm}-${dd} ${parts[1] || '00:00'}`;
    }
    return str;
  };

  analiticoState.filteredData.sort((a, b) => {
    let valA = a[col];
    let valB = b[col];

    if (col === 'dias' || col === 'horas') {
      const isNullA = (valA === null || valA === undefined);
      const isNullB = (valB === null || valB === undefined);
      if (isNullA && isNullB) return 0;
      if (isNullA) return 1; // nulos/rondas sempre no final
      if (isNullB) return -1;
      return (Number(valA) - Number(valB)) * dir;
    }

    if (col === 'os') {
      return (Number(valA) - Number(valB)) * dir;
    }

    if (col === 'dt_rec' || col === 'dt_fim') {
      const isNullA = !valA;
      const isNullB = !valB;
      if (isNullA && isNullB) return 0;
      if (isNullA) return 1;
      if (isNullB) return -1;
      const isoA = parseBrDateToIso(valA);
      const isoB = parseBrDateToIso(valB);
      return isoA.localeCompare(isoB) * dir;
    }

    valA = (valA || '').toString().toLowerCase();
    valB = (valB || '').toString().toLowerCase();
    return valA.localeCompare(valB) * dir;
  });

  renderAnaliticoTable();
}

function renderAnaliticoTable() {
  const tbody = document.getElementById('analitico-tbody');
  if (!tbody) return;

  const total = analiticoState.filteredData ? analiticoState.filteredData.length : 0;
  const pageSize = analiticoState.pageSize || 25;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  // Prevenção estrita contra NaN
  if (!analiticoState.currentPage || isNaN(analiticoState.currentPage) || analiticoState.currentPage < 1) {
    analiticoState.currentPage = 1;
  }
  if (analiticoState.currentPage > totalPages) {
    analiticoState.currentPage = totalPages;
  }

  const startIdx = (analiticoState.currentPage - 1) * pageSize;
  const endIdx = Math.min(startIdx + pageSize, total);
  const pageRows = (analiticoState.filteredData || []).slice(startIdx, endIdx);

  // Paginação info
  const pageInfo = document.getElementById('analitico-page-info');
  if (pageInfo) {
    if (total === 0) {
      pageInfo.textContent = 'Nenhuma ordem encontrada';
    } else {
      pageInfo.textContent = `Mostrando ${(startIdx + 1).toLocaleString('pt-BR')}–${endIdx.toLocaleString('pt-BR')} de ${total.toLocaleString('pt-BR')} ordens (Página ${analiticoState.currentPage} de ${totalPages})`;
    }
  }

  const curPagePill = document.getElementById('analitico-current-page-num');
  if (curPagePill) curPagePill.textContent = analiticoState.currentPage;

  const btnPrev = document.getElementById('analitico-prev');
  const btnFirst = document.getElementById('analitico-first');
  const btnNext = document.getElementById('analitico-next');
  const btnLast = document.getElementById('analitico-last');

  if (btnPrev) btnPrev.disabled = analiticoState.currentPage <= 1;
  if (btnFirst) btnFirst.disabled = analiticoState.currentPage <= 1;
  if (btnNext) btnNext.disabled = analiticoState.currentPage >= totalPages;
  if (btnLast) btnLast.disabled = analiticoState.currentPage >= totalPages;

  if (pageRows.length === 0) {
    const isHistoric = dateFilterState.inicio && (dateFilterState.inicio.startsWith('2025') || dateFilterState.inicio.startsWith('2024') || dateFilterState.inicio.startsWith('2023'));
    if (isHistoric) {
      tbody.innerHTML = `
        <tr>
          <td colspan="10" style="text-align: center; padding: 48px 24px; color: var(--text-dim);">
            <div style="font-size: 2.2rem; margin-bottom: 12px; color: var(--accent-blue);"><i class="fa-solid fa-calendar-check"></i></div>
            <div style="font-weight: 700; font-size: 1.05rem; color: var(--text-main); margin-bottom: 6px;">
              Período Histórico (${escapeHtml(dateFilterState.label || 'Ano Anterior')})
            </div>
            <div style="font-size: 0.85rem; color: var(--text-muted); max-width: 600px; margin: 0 auto; line-height: 1.6;">
              Nenhum chamado de backlog pendente neste período (Backlog = 0). O detalhamento linha a linha individual cobre o exercício operacional de 2026 e o Backlog Ativo.<br>
              Os <strong>21.798 atendimentos de 2025</strong> estão consolidados nos gráficos executivos do <strong>Cockpit</strong>.
            </div>
          </td>
        </tr>
      `;
    } else {
      tbody.innerHTML = `
        <tr>
          <td colspan="10" style="text-align: center; padding: 40px 20px; color: var(--text-dim);">
            <div style="font-size: 1.8rem; margin-bottom: 8px;"><i class="fa-solid fa-magnifying-glass"></i></div>
            <div style="font-weight: 600; font-size: 0.95rem; color: var(--text-main);">Nenhum chamado encontrado para os filtros selecionados.</div>
            <div style="font-size: 0.8rem; margin-top: 4px;">Tente alterar os termos da busca ou clique em <strong>Limpar Filtros</strong>.</div>
          </td>
        </tr>
      `;
    }
    return;
  }

  tbody.innerHTML = pageRows.map(r => {
    // Badge Origem
    let origemBadge = '';
    const orig = (r.origem || '').toLowerCase();
    if (orig.includes('call center')) {
      origemBadge = `<span class="badge badge-info" style="font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-headset" style="margin-right: 4px;"></i>Call Center</span>`;
    } else if (orig.includes('ronda própria') || orig.includes('ronda propria')) {
      origemBadge = `<span class="badge badge-warning" style="font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-shield-halved" style="margin-right: 4px;"></i>Ronda Própria</span>`;
    } else if (orig.includes('ronda')) {
      origemBadge = `<span class="badge badge-secondary" style="font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-shield-halved" style="margin-right: 4px;"></i>Ronda Interna</span>`;
    } else if (orig.includes('telegest')) {
      origemBadge = `<span class="badge" style="background: rgba(99, 102, 241, 0.15); color: #818cf8; border: 1px solid rgba(99, 102, 241, 0.3); font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-tower-broadcast" style="margin-right: 4px;"></i>Telegestão</span>`;
    } else if (orig.includes('app')) {
      origemBadge = `<span class="badge" style="background: rgba(168, 85, 247, 0.15); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.3); font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-mobile-screen" style="margin-right: 4px;"></i>App</span>`;
    } else if (orig.includes('internet')) {
      origemBadge = `<span class="badge" style="background: rgba(14, 165, 233, 0.15); color: #38bdf8; border: 1px solid rgba(14, 165, 233, 0.3); font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-globe" style="margin-right: 4px;"></i>Internet</span>`;
    } else if (orig.includes('chatbot')) {
      origemBadge = `<span class="badge" style="background: rgba(236, 72, 153, 0.15); color: #f472b6; border: 1px solid rgba(236, 72, 153, 0.3); font-weight: 600; font-size: 0.74rem;"><i class="fa-solid fa-robot" style="margin-right: 4px;"></i>Chatbot</span>`;
    } else {
      origemBadge = `<span class="badge badge-secondary" style="font-size: 0.74rem;">${escapeHtml(r.origem || 'Não Informada')}</span>`;
    }

    // Badge SLA em Dias (arredondado para número inteiro)
    let tmaBadge = '';
    if (r.is_pendente) {
      const dInt = Math.round(r.dias || 0);
      if (r.alerta_auditoria) {
        tmaBadge = `<span class="tma-badge tma-badge-danger" title="${escapeHtml(r.tempo_restante_texto || 'Aguardando regularização CCO')}"><i class="fa-solid fa-triangle-exclamation"></i> ${dInt}d <small>(Aberto)</small></span>`;
      } else if (r.sla === 'Atrasado') {
        tmaBadge = `<span class="tma-badge tma-badge-danger" title="${escapeHtml(r.tempo_restante_texto || 'Atraso no backlog')}"><i class="fa-solid fa-triangle-exclamation"></i> ${dInt}d <small>(Atraso)</small></span>`;
      } else {
        tmaBadge = `<span class="tma-badge tma-badge-ontime" title="${escapeHtml(r.tempo_restante_texto || 'Dentro do prazo')}"><i class="fa-solid fa-clock"></i> ${dInt}d <small>(Restam)</small></span>`;
      }
    } else if (r.dias === null || r.dias === undefined) {
      tmaBadge = `<span class="badge badge-secondary" title="Atendimento originado em ronda interna (Sem chamado)"><i class="fa-solid fa-shield-halved"></i> Ronda</span>`;
    } else {
      const dInt = Math.round(r.dias);
      const hInt = r.horas ? Math.round(r.horas) : Math.round(r.dias * 24);
      const recDate = r.dt_rec || 'Não informada';
      const fimDate = r.dt_fim || 'Não informada';
      const tooltipFormula = `SLA / Tempo de Resolução: ${dInt} dias (~${hInt}h) | Conclusão: ${fimDate} - Reclamação: ${recDate}`;
      if (r.dias <= 1.0) {
        tmaBadge = `<span class="tma-badge tma-badge-quick" title="${escapeHtml(tooltipFormula)}"><i class="fa-solid fa-bolt"></i> ${dInt}d <small>(${hInt}h)</small></span>`;
      } else if (r.dias <= 3.0) {
        tmaBadge = `<span class="tma-badge tma-badge-ontime" title="${escapeHtml(tooltipFormula)}"><i class="fa-solid fa-stopwatch"></i> ${dInt}d <small>(${hInt}h)</small></span>`;
      } else if (r.dias <= 7.0) {
        tmaBadge = `<span class="tma-badge tma-badge-warning" title="${escapeHtml(tooltipFormula)}"><i class="fa-solid fa-triangle-exclamation"></i> ${dInt}d <small>(${hInt}h)</small></span>`;
      } else {
        tmaBadge = `<span class="tma-badge tma-badge-danger" title="${escapeHtml(tooltipFormula)}"><i class="fa-solid fa-circle-exclamation"></i> ${dInt}d <small>(${hInt}h)</small></span>`;
      }
    }

    // Badge SLA
    let slaBadge = '';
    if (r.alerta_auditoria) {
      slaBadge = `<span class="badge badge-danger" style="background: rgba(239, 68, 68, 0.16); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.4);"><i class="fa-solid fa-triangle-exclamation"></i> Detectado Exclusão</span>`;
    } else if (r.is_pendente) {
      if (r.sla === 'Atrasado') {
        slaBadge = `<span class="badge badge-danger"><i class="fa-solid fa-clock"></i> Backlog Vencido</span>`;
      } else {
        slaBadge = `<span class="badge badge-success"><i class="fa-solid fa-clock"></i> Backlog no Prazo</span>`;
      }
    } else if (r.sla === 'No Prazo') {
      slaBadge = `<span class="badge badge-success"><i class="fa-solid fa-check"></i> No Prazo</span>`;
    } else if (r.sla === 'Atrasado') {
      slaBadge = `<span class="badge badge-danger"><i class="fa-solid fa-triangle-exclamation"></i> Atrasado</span>`;
    } else {
      slaBadge = `<span class="badge badge-secondary"><i class="fa-solid fa-shield-halved"></i> Ronda</span>`;
    }

    // Badge Auditoria Exclusão no número da OS
    let badgeExclusaoOs = '';
    if (r.alerta_auditoria) {
      badgeExclusaoOs = `
        <span class="badge-exclusao" title="Detectado Exclusão: Essa solicitação não se enconta na base de itens pendentes e ela não foi migrada para para itens concluídos, o sistema mantém essa solicitação até ela entrar no status de concluído.">
          <span>Detectado Exclusão</span>
          <span class="badge-info-icon"><i class="fa-solid fa-circle-info"></i></span>
          <div class="badge-tooltip-popup">
            <strong><i class="fa-solid fa-circle-info"></i> Detectado Exclusão</strong>
            Essa solicitação não se enconta na base de itens pendentes e ela não foi migrada para para itens concluídos, o sistema mantém essa solicitação até ela entrar no status de concluído.
          </div>
        </span>`;
    } else if (r.is_pendente) {
      badgeExclusaoOs = `<span class="badge badge-warning" style="font-size:0.7rem; margin-left: 4px; padding: 1px 5px;"><i class="fa-solid fa-clock-rotate-left"></i> Pendente</span>`;
    }

    const protoText = r.proto ? `<span style="font-size:0.75rem; color:var(--text-dim); display:block;">Prot: ${escapeHtml(r.proto)}</span>` : '<span style="font-size:0.75rem; color:var(--text-dim); display:block;">Sem protocolo</span>';
    const dtRecHtml = r.dt_rec === 'Ronda Interna' ? '<span class="badge badge-secondary" style="font-size:0.72rem;">Ronda Interna</span>' : escapeHtml(r.dt_rec);
    const dtFimHtml = r.is_pendente
      ? `<span class="badge badge-warning" style="font-size: 0.72rem; font-weight: 700; background: rgba(234, 179, 8, 0.15); color: #eab308; border: 1px solid rgba(234, 179, 8, 0.3);"><i class="fa-solid fa-hourglass-half" style="margin-right: 3px;"></i>Em Aberto</span>`
      : escapeHtml(r.dt_fim || '-');
    const solucaoHtml = r.is_pendente
      ? `<span style="color: var(--warning); font-weight: 600;"><i class="fa-solid fa-wrench" style="margin-right: 4px;"></i>${escapeHtml(r.solucao || 'Em Atendimento')}</span>`
      : escapeHtml(r.solucao || '-');

    return `
      <tr>
        <td style="white-space: nowrap;">
          <div style="display: inline-flex; align-items: center; flex-wrap: wrap;">
            <strong style="color: var(--primary);">#${r.os}</strong>
            ${badgeExclusaoOs}
          </div>
          ${protoText}
        </td>
        <td style="white-space: nowrap;">${origemBadge}</td>
        <td style="white-space: nowrap;">${dtRecHtml}</td>
        <td style="white-space: nowrap;">${dtFimHtml}</td>
        <td style="white-space: nowrap;">${tmaBadge}</td>
        <td style="white-space: nowrap;">${slaBadge}</td>
        <td style="white-space: nowrap;"><strong>${escapeHtml(r.eq)}</strong></td>
        <td>${escapeHtml(r.bairro)}</td>
        <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${escapeHtml(r.tipo)}">
          ${escapeHtml(r.tipo)}
        </td>
        <td style="max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${escapeHtml(r.solucao || '-')}">
          ${solucaoHtml}
        </td>
      </tr>
    `;
  }).join('');
}

function exportarAnaliticoExcel() {
  if (typeof XLSX === 'undefined') {
    showToast('Biblioteca SheetJS (XLSX) não disponível.');
    return;
  }

  const exportRows = analiticoState.filteredData.map(r => ({
    'Ordem de Serviço (OS)': r.os,
    'Protocolo': r.proto || '-',
    'Origem': r.origem || 'Não Informada',
    'Data Reclamação': r.dt_rec,
    'Data Conclusão': r.dt_fim || (r.is_pendente ? 'Em Aberto' : '-'),
    'SLA (Dias)': r.dias !== null ? r.dias : 'Ronda Interna',
    'SLA (Horas)': r.horas !== null ? r.horas : '-',
    'Status SLA': r.sla,
    'Situação Operacional': r.is_pendente ? (r.alerta_auditoria ? 'Backlog (Detectado Exclusão)' : 'Pendente em Aberto') : 'Concluído',
    'Equipe': r.eq,
    'Bairro': r.bairro,
    'Defeito / Ocorrência': r.tipo,
    'Solução Aplicada': r.solucao || (r.is_pendente ? 'Em Atendimento' : '-'),
    'Nota de Auditoria CCO': r.audit_nota || (r.is_pendente ? 'Item ativo em fila operacional' : 'Atendimento concluído e registrado no SGI')
  }));

  const ws = XLSX.utils.json_to_sheet(exportRows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Solicitacoes_Full_2026');
  XLSX.writeFile(wb, `Auditoria_Solicitacoes_Exati_${new Date().toISOString().slice(0, 10)}.xlsx`);
  showToast(`Planilha exportada com sucesso! (${exportRows.length.toLocaleString('pt-BR')} linhas)`);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ==========================================
// EVENTOS & UTILITÁRIOS
// ==========================================
let themeBeforePrint = null;

function prepararImpressao() {
  const printPeriodo = document.getElementById('print-periodo');
  const printEmissao = document.getElementById('print-data-emissao');
  const lblBtn = document.getElementById('filter-btn-label');
  const countBtn = document.getElementById('filter-btn-count');

  if (printPeriodo && lblBtn) {
    printPeriodo.textContent = lblBtn.textContent + (countBtn ? ` (${countBtn.textContent})` : '');
  }
  if (printEmissao) {
    const agora = new Date();
    printEmissao.textContent = 'Emitido em: ' + agora.toLocaleDateString('pt-BR') + ' às ' + agora.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  }
}

function setupEventListeners() {
  const filterBtns = document.querySelectorAll('.filter-btn');
  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      filtroAtual = btn.getAttribute('data-filter');
      renderPendentesTable();
    });
  });

  const inputSearch = document.getElementById('input-busca-pendentes');
  if (inputSearch) {
    inputSearch.addEventListener('input', (e) => {
      buscaAtual = e.target.value.trim();
      renderPendentesTable();
    });
  }

  const btnPrint = document.getElementById('btn-imprimir-relatorio');
  if (btnPrint) {
    btnPrint.addEventListener('click', () => {
      prepararImpressao();
      const curTheme = document.documentElement.getAttribute('data-theme');
      if (curTheme === 'dark') {
        themeBeforePrint = 'dark';
        document.documentElement.setAttribute('data-theme', 'light');
        destroyAllCharts();
        renderCharts();
        updateSimulation();
      }
      setTimeout(() => {
        window.print();
      }, 100);
    });
  }

  window.addEventListener('beforeprint', () => {
    prepararImpressao();
    const curTheme = document.documentElement.getAttribute('data-theme');
    if (curTheme === 'dark' && !themeBeforePrint) {
      themeBeforePrint = 'dark';
      document.documentElement.setAttribute('data-theme', 'light');
      destroyAllCharts();
      renderCharts();
      updateSimulation();
    }
  });

  window.addEventListener('afterprint', () => {
    if (themeBeforePrint === 'dark') {
      themeBeforePrint = null;
      document.documentElement.setAttribute('data-theme', 'dark');
      destroyAllCharts();
      renderCharts();
      updateSimulation();
    }
  });

  const btnExportExcel = document.getElementById('btn-exportar-excel');
  if (btnExportExcel) {
    btnExportExcel.addEventListener('click', () => {
      exportarParaExcel();
    });
  }

  const copyBtns = document.querySelectorAll('.btn-copy');
  copyBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const codeId = btn.getAttribute('data-code');
      const codeEl = document.getElementById(codeId);
      if (codeEl) {
        navigator.clipboard.writeText(codeEl.innerText);
        showToast('Código DAX copiado com sucesso!');
      }
    });
  });

  // Clique no aviso do topo para exibir detalhes das bases
  const topbarSyncNotice = document.getElementById('topbar-sync-notice');
  if (topbarSyncNotice) {
    topbarSyncNotice.addEventListener('click', () => {
      const meta = dashboardData.metadata || {};
      const atHora = meta.atendidos_data_hora || '08/10/2026 09:32';
      const peHora = meta.pendentes_data_hora || '08/10/2026 09:55';
      const atArq = meta.atendidos_arquivo || 'Planilha SGI (Atendidos)';
      const peArq = meta.pendentes_arquivo || 'Planilha Backlog (Pendentes)';
      showToast(`Atendidos: ${atHora} (${atArq}) | Pendentes: ${peHora} (${peArq})`, 'fa-circle-info');
    });
  }

  // Alternância de visualização da Linha do Tempo do Backlog (Diária vs Marcos)
  const btnTlDiaria = document.getElementById('btn-tl-diaria');
  const btnTlMarcos = document.getElementById('btn-tl-marcos');
  if (btnTlDiaria && btnTlMarcos) {
    btnTlDiaria.addEventListener('click', () => {
      timelineViewMode = 'diaria';
      btnTlDiaria.classList.add('active');
      btnTlMarcos.classList.remove('active');
      btnTlDiaria.style.background = 'var(--primary)';
      btnTlDiaria.style.color = '#fff';
      btnTlMarcos.style.background = 'transparent';
      btnTlMarcos.style.color = 'var(--text-dim)';
      renderChartEvolucaoPendentes();
    });
    btnTlMarcos.addEventListener('click', () => {
      timelineViewMode = 'marcos';
      btnTlMarcos.classList.add('active');
      btnTlDiaria.classList.remove('active');
      btnTlMarcos.style.background = 'var(--primary)';
      btnTlMarcos.style.color = '#fff';
      btnTlDiaria.style.background = 'transparent';
      btnTlDiaria.style.color = 'var(--text-dim)';
      renderChartEvolucaoPendentes();
    });
  }

  // Controles do Banner de Filtro Interativo do Gráfico do Backlog
  const btnLimparFiltroGrafico = document.getElementById('btn-limpar-filtro-grafico');
  if (btnLimparFiltroGrafico) {
    btnLimparFiltroGrafico.addEventListener('click', () => {
      filtroGraficoData = null;
      filtroAtual = 'todos';
      buscaAtual = '';
      const inputSearch = document.getElementById('input-busca-pendentes');
      if (inputSearch) inputSearch.value = '';
      const filterBtns = document.querySelectorAll('.filter-btn');
      filterBtns.forEach(b => {
        if (b.getAttribute('data-filter') === 'todos') b.classList.add('active');
        else b.classList.remove('active');
      });
      const banner = document.getElementById('banner-filtro-grafico');
      if (banner) banner.style.display = 'none';
      renderPendentesTable();
      showToast('Filtro removido: exibindo lista completa do backlog pendente');
    });
  }

  const btnFiltroAcumulado = document.getElementById('btn-filtro-acumulado');
  const btnFiltroDia = document.getElementById('btn-filtro-dia');
  if (btnFiltroAcumulado && btnFiltroDia) {
    btnFiltroAcumulado.addEventListener('click', () => {
      if (!filtroGraficoData) return;
      filtroGraficoData.mode = 'acumulado';
      btnFiltroAcumulado.classList.add('active');
      btnFiltroDia.classList.remove('active');
      renderPendentesTable();
    });

    btnFiltroDia.addEventListener('click', () => {
      if (!filtroGraficoData) return;
      filtroGraficoData.mode = 'dia';
      btnFiltroDia.classList.add('active');
      btnFiltroAcumulado.classList.remove('active');
      renderPendentesTable();
    });
  }

  // Controles de Granularidade e Drill-Down do Gráfico Principal (Power BI)
  const btnDrillMes = document.getElementById('btn-drill-mes');
  const btnDrillDia = document.getElementById('btn-drill-dia');
  const btnDrillUp = document.getElementById('btn-drill-up');

  if (btnDrillMes) {
    btnDrillMes.addEventListener('click', () => {
      evolucaoGranularidade = 'mes';
      evolucaoDrillMonth = null;
      renderCharts();
      showToast('Visualização consolidada por Mês (Padrão)', 'fa-calendar-days');
    });
  }

  if (btnDrillDia) {
    btnDrillDia.addEventListener('click', () => {
      evolucaoGranularidade = 'dia';
      renderCharts();
      showToast('Nível descido: visualizando atendimentos por Dia', 'fa-arrow-down');
    });
  }

  if (btnDrillUp) {
    btnDrillUp.addEventListener('click', () => {
      evolucaoGranularidade = 'mes';
      evolucaoDrillMonth = null;
      renderCharts();
      showToast('Subiu de nível: retornando à visão consolidada por Mês', 'fa-arrow-up');
    });
  }

  // Seletor de Ocorrência para Comparativo Geográfico por Bairro
  const selOcorrenciaBairro = document.getElementById('select-ocorrencia-bairro');
  if (selOcorrenciaBairro) {
    selOcorrenciaBairro.value = selectedOcorrenciaBairro;
    selOcorrenciaBairro.addEventListener('change', (e) => {
      selectedOcorrenciaBairro = e.target.value;
      renderBairroOcorrenciaSlaChart();
    });
  }

  // Efeito dinâmico de elevação no header sticky durante a rolagem
  const stickyWrapper = document.getElementById('sticky-header-wrapper');
  if (stickyWrapper) {
    const handleScroll = () => {
      if (window.scrollY > 6) {
        stickyWrapper.classList.add('is-scrolled');
      } else {
        stickyWrapper.classList.remove('is-scrolled');
      }
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
  }
}

function renderBairroOcorrenciaSlaChart() {
  const ctx = document.getElementById('chartBairroOcorrenciaSla');
  if (!ctx) return;
  if (chartBairroOcorrenciaSla) chartBairroOcorrenciaSla.destroy();

  const defaults = getChartDefaults();
  const atend2026 = dashboardData.atendidos_2026 || [];

  const filtradosAtend = atend2026.filter(r => {
    if (!r.data_iso) return true;
    return r.data_iso >= dateFilterState.inicio && r.data_iso <= dateFilterState.fim;
  });

  const isAll = selectedOcorrenciaBairro === 'Todas as Ocorrências';
  const rows = filtradosAtend.filter(r => {
    if (r.dias === null || r.dias === undefined) return false;
    if (isAll) return true;
    return r.tipo === selectedOcorrenciaBairro;
  });

  const bairroMap = {};
  rows.forEach(r => {
    const b = r.bairro || 'Não Informado';
    if (!bairroMap[b]) bairroMap[b] = { soma: 0, count: 0 };
    bairroMap[b].soma += r.dias;
    bairroMap[b].count++;
  });

  const minOrders = isAll ? 4 : 2;
  let bairrosList = Object.keys(bairroMap)
    .filter(b => bairroMap[b].count >= minOrders && b !== 'NÃO ENCONTRADO')
    .map(b => {
      const item = bairroMap[b];
      const avg = item.count > 0 ? (item.soma / item.count) : 0;
      return {
        bairro: b,
        sla: Math.round(avg),
        total: item.count
      };
    })
    .sort((a, b) => b.sla - a.sla)
    .slice(0, 10);

  const diagBox = document.getElementById('bairro-diagnostico-box');

  let isFallback = false;
  if (bairrosList.length === 0) {
    const fallbackMap = (dashboardData.series && dashboardData.series.ocorrencias_bairro_map) || {};
    const fallbackArr = fallbackMap[selectedOcorrenciaBairro] || fallbackMap['Todas as Ocorrências'] || [];
    if (fallbackArr.length > 0) {
      isFallback = true;
      bairrosList = fallbackArr.map(item => ({
        bairro: item.bairro,
        sla: Math.round(item.sla_medio || item.sla_mediana || 2),
        total: item.total || 0
      })).slice(0, 10);
    }
  }

  if (bairrosList.length === 0) {
    if (diagBox) {
      diagBox.innerHTML = '<span style="color: var(--text-dim);">Poucos chamados com tempo registrado para esta ocorrência no filtro atual. Tente selecionar <strong>Todas as Ocorrências</strong> ou ampliar o período.</span>';
    }
    return;
  }

  const labels = bairrosList.map(item => item.bairro);
  const dataSla = bairrosList.map(item => item.sla);
  const extraCounts = bairrosList.map(item => `${item.total} OS`);

  const bgColors = dataSla.map(sla => {
    if (sla >= 4) return 'rgba(239, 68, 68, 0.75)';
    if (sla >= 2) return 'rgba(245, 158, 11, 0.75)';
    return 'rgba(16, 185, 129, 0.75)';
  });

  const borderColors = dataSla.map(sla => {
    if (sla >= 4) return '#ef4444';
    if (sla >= 2) return '#f59e0b';
    return '#10b981';
  });

  chartBairroOcorrenciaSla = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [{
        label: 'SLA (Dias)',
        data: dataSla,
        backgroundColor: bgColors,
        borderColor: borderColors,
        borderWidth: 1.5,
        borderRadius: 4
      }]
    },
    options: {
      ...defaults,
      indexAxis: 'y',
      plugins: {
        ...defaults.plugins,
        extraCounts: extraCounts,
        legend: { display: false },
        tooltip: {
          ...defaults.plugins.tooltip,
          callbacks: {
            label: (ctx) => {
              const item = bairrosList[ctx.dataIndex];
              return [
                `SLA: ${Math.round(item.sla)} dias`,
                `Volume no Bairro: ${item.total} ordens`
              ];
            }
          }
        }
      },
      scales: {
        ...defaults.scales,
        x: {
          ...defaults.scales.x,
          title: {
            display: true,
            text: 'SLA de Atendimento (Dias)',
            color: defaults.color,
            font: { family: 'Inter', size: 10, weight: '600' }
          },
          grace: '25%'
        }
      }
    }
  });

  // Diagnóstico Dinâmico Comparativo
  if (diagBox && bairrosList.length >= 2) {
    const highest = bairrosList[0];
    const lowest = bairrosList[bairrosList.length - 1];
    const ratio = lowest.sla > 0 ? (highest.sla / lowest.sla).toFixed(1) : (highest.sla).toFixed(0);
    const subNotice = isFallback
      ? `<div style="display:inline-block; margin-bottom:4px; font-size:0.75rem; color:var(--accent-blue);"><i class="fa-solid fa-circle-info"></i> Referência histórica consolidada para este defeito</div><br>`
      : '';

    diagBox.innerHTML = `
      <div style="display: flex; gap: 8px; align-items: flex-start;">
        <i class="fa-solid fa-lightbulb" style="color: var(--warning, #f59e0b); font-size: 1.15rem; margin-top: 2px;"></i>
        <div>
          ${subNotice}
          <div style="font-weight: 700; color: var(--text-main); margin-bottom: 3px;">
            Diagnóstico de Variação de Prazo • <em>${escapeHtml(selectedOcorrenciaBairro)}</em>
          </div>
          <div style="color: var(--text-muted); font-size: 0.78rem;">
            O SLA varia de <strong style="color: #10b981;">${Math.round(lowest.sla)}d em ${lowest.bairro}</strong> até <strong style="color: #ef4444;">${Math.round(highest.sla)}d em ${highest.bairro}</strong> (discrepância de <strong>${ratio}x</strong>).
            ${highest.sla >= 4 ? 'Bairros periféricos ou com malha viária mais extensa demandam maior tempo de deslocamento das viaturas, enquanto bairros no eixo central contam com rotas diárias de manutenção.' : 'Todos os bairros analisados mantêm prazos ágeis e homogêneos dentro da meta.'}
          </div>
        </div>
      </div>
    `;
  }
}

function exportarParaExcel() {
  if (typeof XLSX === 'undefined') {
    window.location.href = './base_consolidada_powerbi.xlsx';
    return;
  }

  const wb = XLSX.utils.book_new();
  const wsPendentes = XLSX.utils.json_to_sheet(dashboardData.pendentes_lista);
  XLSX.utils.book_append_sheet(wb, wsPendentes, 'Backlog_Pendentes');

  const resumoData = [
    { Indicador: 'Período Filtrado Início', Valor: dateFilterState.inicio },
    { Indicador: 'Período Filtrado Fim', Valor: dateFilterState.fim },
    { Indicador: 'Total Histórico Atendidos', Valor: dashboardData.kpis.total_historico_atendidos },
    { Indicador: 'SLA de Atendimento (Dias)', Valor: dashboardData.kpis.tma_dias_medio + ' dias' },
    { Indicador: 'Backlog Ativo (Ordens)', Valor: dashboardData.kpis.total_pendentes_chamados },
    { Indicador: 'Backlog Ativo (Pontos Físicos)', Valor: dashboardData.kpis.total_pendentes_pontos }
  ];
  const wsResumo = XLSX.utils.json_to_sheet(resumoData);
  XLSX.utils.book_append_sheet(wb, wsResumo, 'Resumo_KPIs');

  XLSX.writeFile(wb, `Monitor_Exati_Relatorio_${dateFilterState.inicio}_a_${dateFilterState.fim}.xlsx`);
  showToast('Planilha Excel gerada e baixada com sucesso!');
}

